/* MathQuest — EVARS et orientation au collège, année scolaire 2026-2027 : 32 chapitres reconstruits (evars6a … evars3c, orientation6a … orientation3e).
   EVARS : programme d’éducation à la vie affective et relationnelle, et à la sexualité, BO n°6 du 6 février 2025 (NOR MENE2503064A),
   applicable depuis la rentrée 2025 ; au moins trois séances spécifiques par an (article L. 312-16 du Code de l’éducation), une par axe.
   Pour chaque niveau, les trois chapitres suivent l’objectif d’apprentissage officiel de l’axe correspondant et ses « notions et compétences »
   (texte du programme, partie Collège, et livret d’accompagnement Éduscol de 6e, 2026). Aucun contenu non prévu par le programme n’est ajouté ;
   vocabulaire adapté à l’âge ; les ressources d’aide citées sont celles du programme (adultes de confiance, infirmerie, 119, 3018, centres
   de santé sexuelle, CeGIDD) et les numéros nationaux gratuits.
   Orientation : parcours Avenir (arrêté du 1er juillet 2015, BO n°28 du 9 juillet 2015), découverte des métiers au collège, séquence
   d’observation en milieu professionnel en 3e (Code de l’éducation), procédure d’orientation et d’affectation après la 3e. */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,txt,order,tf,bank,pairs,sort,seq,mix,pickN,shuffle,nf}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const EV='Programme d’éducation à la vie affective et relationnelle, et à la sexualité (EVARS), BO n°6 du 6 février 2025 (NOR MENE2503064A), partie Collège';
const AX1='EVARS — axe « Se connaître, vivre et grandir avec son corps »',AX2='EVARS — axe « Rencontrer les autres et construire des relations, s’y épanouir »',AX3='EVARS — axe « Trouver sa place dans la société, y être libre et responsable »';
const OBJ=(n,o)=>`Objectif d’apprentissage de ${n} : « ${o} »`;
const L312='Article L. 312-16 du Code de l’éducation (au moins trois séances annuelles)';
const LIV='Éduscol — livret d’accompagnement du programme EVARS, classe de sixième (2026)';
const AV='Parcours Avenir — arrêté du 1er juillet 2015, BO n°28 du 9 juillet 2015';
const ONI='Onisep — ressources d’information sur les métiers et les formations (onisep.fr)';
const OBS='Code de l’éducation — séquence d’observation en milieu professionnel des élèves de 3e';
const PROC='Procédure d’orientation et d’affectation après la classe de troisième (dialogue famille-établissement, conseil de classe, affectation en lycée)';

MQ.add('evars','6',[
{id:'evars6a',name:'La puberté : comprendre les changements de son corps',icon:'🌱',domain:'Se connaître et grandir',
 refs:[AX1,OBJ('6e','Comprendre et apprendre à vivre les changements de son corps'),EV,LIV],
 tip:'Chacun son rythme : la puberté commence et se termine à des âges différents selon les personnes, et c’est normal.',
 c:C(`Entre environ 8 et 17 ans, le corps change : c’est la <b>puberté</b>. Elle fait partie de l’<b>adolescence</b>. Ces changements sont à la fois physiques, physiologiques, psychologiques et affectifs, et ils ne se produisent pas au même âge pour tout le monde.`,
  [T('Des changements dans tout le corps',`<p><b>Physiques</b> : croissance rapide, poils, transpiration plus importante, peau plus grasse (boutons), voix qui mue, poitrine qui se développe. <b>Physiologiques</b> : les organes reproducteurs deviennent fonctionnels (premières règles, premières éjaculations). <b>Psychologiques et affectifs</b> : émotions plus fortes, besoin d’intimité, nouvelles attirances, regard différent sur soi.</p><p>Ces changements sont commandés par des <b>hormones</b>.</p>`),
   T('Chacun son rythme, chacun son corps',`<p>Chaque personne a un corps <b>unique</b> : taille, morphologie, rythme de développement varient beaucoup. Se comparer n’a pas de sens. On prend soin de son corps (hygiène, sommeil, alimentation) et on respecte celui des autres.</p><p>Des <b>règles douloureuses</b> ne sont pas « normales à supporter » : elles nécessitent une <b>consultation médicale</b>. Pour toute question : l’infirmerie du collège, un médecin, des sources fiables adaptées à son âge.</p>`)],
  [{q:'Lina, 11 ans, s’inquiète : ses amies ont grandi et pas elle. Que lui répondre ?',s:['La puberté commence et se termine à des âges différents selon les personnes.','Il n’y a pas un modèle unique : chaque corps a son rythme.','Si elle a une inquiétude, elle peut en parler à l’infirmier ou l’infirmière du collège ou à un médecin.']}],
  ['Je connais les principaux changements de la puberté.','Je sais que chacun a son rythme.','Je prends soin de mon corps (hygiène, sommeil).','Je sais à qui poser mes questions.'],
  ['Croire que tout le monde doit changer au même âge.','Se moquer du corps des autres.','Penser que des règles très douloureuses sont normales et ne pas consulter.'],
  ['Puberté : changements physiques, physiologiques, psychologiques, affectifs.','Rythmes différents selon chacun.','Questions : infirmerie, médecin, adulte de confiance.']),
 g:mix([sort({'Changement physique':['la voix qui mue','la croissance rapide','l’apparition de poils','la peau plus grasse'],'Changement psychologique ou affectif':['des émotions plus fortes','un besoin d’intimité plus grand','de nouvelles attirances','un regard différent sur soi']},{q:'« %s » : de quel type de changement s’agit-il ?'}),2],
  [bank([
   ['La puberté commence-t-elle au même âge pour tout le monde ?','non, chacun a son propre rythme',['oui, à 12 ans exactement','oui, le jour de l’entrée au collège','oui, pour toutes les filles et tous les garçons'],'Elle commence et se termine à des âges différents.'],
   ['Qu’est-ce qui déclenche les changements de la puberté ?','des hormones',['le sport','la nourriture seulement','le collège'],'Les hormones agissent sur tout le corps.'],
   ['Des règles très douloureuses…','nécessitent une consultation médicale',['sont toujours normales','doivent être cachées','passent toujours seules'],'C’est ce que rappelle le programme.'],
   ['La puberté fait partie…','de l’adolescence',['de la petite enfance','de la vieillesse','des vacances'],'C’est le passage de l’enfance à l’adolescence.'],
   ['Un camarade se moque de la voix qui mue d’un autre élève. C’est…','un manque de respect',['une bonne blague','normal','un encouragement'],'Chacun vit ces changements à son rythme.'],
   ['Avec la puberté, la transpiration augmente. Que faire ?','prendre une douche régulièrement et changer de vêtements',['ne plus faire de sport','ne rien changer','se parfumer sans se laver'],'L’hygiène aide à se sentir bien.'],
   ['Où trouver des informations fiables sur la puberté ?','auprès de l’infirmerie, d’un médecin ou de sources adaptées à son âge',['dans des rumeurs de cour','dans des vidéos sans auteur','nulle part'],'Les sources fiables évitent les idées fausses.'],
   ['Chaque personne a un corps…','unique, avec ses propres particularités',['identique à celui des autres','qui doit ressembler aux images des publicités','qu’il faut comparer'],'Taille et morphologie varient beaucoup.'],
   ['Les émotions plus fortes à l’adolescence…','font partie des changements de la puberté',['sont un signe de maladie','sont interdites','n’existent pas'],'Les changements sont aussi psychologiques et affectifs.',2],
   {tf:'Les changements de la puberté sont seulement physiques.',v:false,e:'Ils sont aussi physiologiques, psychologiques et affectifs.'},
   {tf:'Se comparer aux autres n’a pas de sens, car chacun grandit à son rythme.',v:true,e:'Il n’y a pas de modèle unique.'},
   ['Porter un regard bienveillant sur soi, c’est par exemple…','nommer ses forces et ses qualités',['critiquer son reflet','se comparer sans arrêt','cacher ses qualités'],'C’est une démarche proposée par le programme.',2]]),3])},

{id:'evars6b',name:'Relations avec les autres et respect de l’intimité',icon:'🤝',domain:'Relations aux autres',
 refs:[AX2,OBJ('6e','Entrer en relation avec les autres et comprendre que les relations peuvent changer'),EV,LIV],
 tip:'Avant de publier ou de transférer une photo ou un message sur quelqu’un, pose-toi la question : est-ce que la personne est d’accord ?',
 c:C(`Au collège, on rencontre de nouvelles personnes ; certaines amitiés se renforcent, d’autres changent. Les <b>relations</b> évoluent, et le <b>numérique</b> en fait désormais partie. Respecter la <b>vie privée</b> et l’<b>intimité</b> de chacun, en ligne comme dans la cour, est une règle de base, protégée par la loi.`,
  [T('Les relations peuvent changer',`<p>Une relation peut aller de l’<b>indifférence</b> à l’<b>intérêt</b>, de la <b>sympathie</b> à l’<b>antipathie</b>. Une relation positive repose sur la <b>confiance</b>, l’<b>échange</b>, le <b>respect</b>, le <b>soutien</b>, l’<b>empathie</b>. Les <b>pairs</b> (les jeunes de son âge) ont une influence, positive (encourager, aider) ou négative (pousser à faire ce qu’on ne veut pas). On a le droit de dire non.</p>`),
   T('Vie privée, intimité et numérique',`<p>La loi protège la <b>vie privée</b> et le <b>droit à l’image</b> : on ne publie pas la photo ou les informations de quelqu’un sans son accord. Se moquer, insulter, exclure de façon répétée, c’est du <b>harcèlement</b> ; en ligne, du <b>cyberharcèlement</b>.</p><p>Victime ou témoin : en parler à un <b>adulte de confiance</b> (parents, CPE, professeur, infirmier ou infirmière), appeler le <b>3018</b> (harcèlement et violences numériques, gratuit et confidentiel) ou le <b>119</b> (enfance en danger).</p>`)],
  [{q:'Dans un groupe de discussion de la classe, une photo d’un élève est partagée avec des moqueries. Que faire ?',s:['Ne pas « liker », ne pas transférer, ne pas commenter.','Garder une trace (capture d’écran) et en parler à un adulte de confiance.','Soutenir l’élève concerné ; le 3018 peut aider à faire supprimer les contenus.']}],
  ['Je reconnais ce qui fait une relation positive.','Je repère l’influence des autres et je peux dire non.','Je respecte la vie privée et l’image des autres.','Victime ou témoin, j’en parle et je demande de l’aide.'],
  ['Transférer une photo « pour rire ».','Penser qu’un témoin silencieux n’a aucun rôle.','Croire qu’il faut rester ami avec quelqu’un qui nous fait du mal.'],
  ['Les relations évoluent.','Vie privée, droit à l’image.','Aide : adulte de confiance, 3018, 119.']),
 g:mix([sort({'Relation positive':['la confiance','le soutien','le respect','l’écoute','l’entraide'],'Relation négative':['les moqueries répétées','l’exclusion volontaire','les menaces','la pression pour faire ce qu’on ne veut pas']},{q:'« %s » caractérise plutôt…'}),2],
  [bank([
   ['Peut-on publier la photo d’un camarade sans son accord ?','non, c’est une atteinte à son droit à l’image',['oui, si elle est drôle','oui, dans un groupe privé','oui, s’il est absent'],'Il faut toujours son accord.'],
   ['Quel numéro gratuit et confidentiel aide en cas de cyberharcèlement ?','le 3018',['le 15','le 3615','le 36 30'],'Il aide aussi à faire supprimer des contenus.'],
   ['Le 119 est le numéro…','de l’enfance en danger',['de la météo','des pompiers uniquement','d’un jeu'],'Gratuit, il fonctionne jour et nuit.'],
   ['Des camarades te poussent à te moquer d’un élève. C’est…','une influence négative des pairs : tu peux refuser',['une obligation','une preuve d’amitié','sans importance'],'On a le droit de dire non.'],
   ['Un ami t’encourage à te remettre au sport après une blessure. C’est…','une influence positive',['une influence négative','du harcèlement','une moquerie'],'Les pairs peuvent aussi aider.'],
   ['Être témoin de harcèlement et ne rien dire…','laisse la situation continuer',['n’a aucune conséquence','protège la victime','est la meilleure solution'],'Le témoin peut agir en parlant à un adulte de confiance.'],
   ['Une amitié qui change avec le temps, c’est…','possible et normal',['interdit','toujours la faute de quelqu’un','impossible'],'Les relations peuvent évoluer.'],
   ['Tu reçois une photo gênante d’un camarade. Que fais-tu ?','je ne la transfère pas et j’en parle à un adulte',['je la transfère à toute la classe','je la publie','je la commente'],'Transférer, c’est participer.'],
   ['L’empathie, c’est…','comprendre ce que ressent l’autre',['ignorer les autres','se moquer','imposer son avis'],'Elle aide à construire des relations positives.',2],
   ['Le harcèlement se caractérise notamment par…','des violences répétées',['un seul désaccord','une dispute entre amis réglée','une compétition sportive'],'C’est la répétition qui le caractérise.',2],
   {tf:'Le cyberharcèlement est puni par la loi.',v:true,e:'C’est un délit.'},
   {tf:'« Liker » un message moqueur n’a aucune importance.',v:false,e:'Cela encourage et amplifie le harcèlement.'},
   ['À qui parler si on est victime de moqueries au collège ?','à un adulte de confiance (CPE, professeur, infirmier ou infirmière, parents)',['à personne','seulement aux harceleurs','sur un réseau social public'],'Les adultes peuvent agir.']]),3])},

{id:'evars6c',name:'Trouver sa place dans un groupe, respecter et être respecté',icon:'🧩',domain:'Vie en société',
 refs:[AX3,OBJ('6e','Trouver sa place au sein d’un groupe sans renier ses propres émotions, respecter les autres et être respecté'),EV,LIV],
 tip:'Une règle s’applique à tous ; un stéréotype est une idée toute faite qui enferme : « les filles sont… », « les garçons sont… ».',
 c:C(`Dans la classe, la cour, une équipe : chacun cherche sa place. Les groupes fonctionnent avec des <b>règles</b>, mais aussi des <b>normes</b> et des <b>stéréotypes</b> qui peuvent exclure. Comprendre ces mécanismes aide à être soi-même tout en respectant les autres.`,
  [T('Règles, normes, modèles, stéréotypes',`<p>Une <b>règle</b> est écrite et s’impose à tous (règlement intérieur, loi). Une <b>norme</b> est une habitude partagée par un groupe (« ce qui se fait »). Un <b>modèle</b> est une personne ou une façon d’être qu’on prend en exemple. Un <b>stéréotype</b> est une idée toute faite, souvent fausse, sur un groupe de personnes (« les filles ne jouent pas au foot »).</p><p>Les stéréotypes peuvent créer des <b>hiérarchies</b> et de l’<b>exclusion</b> (par exemple dans l’occupation de la cour).</p>`),
   T('Être soi-même et respecter les autres',`<p>À la puberté, chacun a la <b>liberté d’être soi-même</b> et le <b>devoir de respecter</b> les autres. Accepter les différences, coopérer, s’entraider permet à chacun de se sentir bien. On a le droit d’exprimer ses émotions. Si l’on est exclu ou rejeté, on en parle à un adulte de confiance.</p>`)],
  [{q:'Dans la cour, le centre est toujours occupé par le foot et les autres élèves restent sur les côtés. Comment analyser ?',s:['Ce n’est pas une règle : c’est une habitude (une norme) du groupe.','Elle peut s’appuyer sur des stéréotypes et exclure certains élèves.','Proposer des solutions : alterner les activités, partager l’espace, en discuter avec le CPE et les délégués.']}],
  ['Je distingue règle, norme, modèle et stéréotype.','Je repère les situations d’exclusion.','Je respecte les différences et je coopère.','J’exprime mes émotions et je demande de l’aide si besoin.'],
  ['Prendre un stéréotype pour une vérité.','Exclure quelqu’un parce qu’il est différent.','Renier ses émotions pour être accepté.'],
  ['Règle : pour tous ; stéréotype : idée toute faite.','Liberté d’être soi et respect des autres.','Coopération, entraide.']),
 g:mix([sort({'Règle':['le règlement intérieur du collège','l’interdiction de frapper un camarade','le code de la route'],'Stéréotype':['« les filles sont moins fortes en maths »','« les garçons ne pleurent pas »','« la danse, c’est pour les filles »','« le foot, c’est pour les garçons »']},{q:'« %s » est…'}),3],
  [bank([
   ['Un stéréotype est…','une idée toute faite, souvent fausse, sur un groupe de personnes',['une règle écrite','une loi','un fait scientifique'],'Il enferme les personnes dans des cases.'],
   ['Une norme, c’est…','une habitude partagée par un groupe',['une loi votée','un sport','une note'],'Elle n’est pas écrite comme une règle.'],
   ['« Les garçons ne pleurent pas » est…','un stéréotype',['une règle du collège','une vérité scientifique','une loi'],'Tout le monde a le droit d’exprimer ses émotions.'],
   ['Un élève est toujours mis à l’écart du groupe. C’est…','une exclusion dont il faut parler',['normal','sans importance','sa faute'],'Personne ne doit être exclu.'],
   ['Coopérer, c’est…','travailler ensemble vers un but commun',['gagner seul','empêcher les autres de jouer','copier'],'La coopération fait une place à chacun.'],
   ['À la puberté, la liberté d’être soi-même va avec…','le devoir de respecter les autres',['le droit de se moquer','l’obligation de ressembler aux autres','le droit d’exclure'],'Liberté et respect vont ensemble.'],
   ['Comment rendre la cour plus égalitaire ?','partager les espaces et alterner les activités',['réserver tout l’espace à un seul jeu','interdire la cour','ne rien changer'],'Chacun doit pouvoir y trouver sa place.',2],
   ['Un modèle, c’est…','une personne ou une façon d’être qu’on prend en exemple',['une règle obligatoire','une punition','un stéréotype forcément faux'],'Il peut être positif ou non.',2],
   {tf:'Un stéréotype peut entraîner de l’exclusion.',v:true,e:'Il crée des hiérarchies entre les personnes.'},
   {tf:'Pour être accepté dans un groupe, il faut cacher ses émotions.',v:false,e:'On peut trouver sa place sans renier ses émotions.'},
   ['L’entraide, c’est…','s’aider les uns les autres',['travailler seul','se disputer','refuser de partager'],'Elle renforce le groupe.']]),2])}
]);

MQ.add('evars','5',[
{id:'evars5a',name:'Développer librement sa personnalité et prendre soin de sa santé',icon:'🌈',domain:'Se connaître et grandir',
 refs:[AX1,OBJ('5e','Développer librement sa personnalité sans se sentir obligé ou contraint'),EV],
 tip:'Être en bonne santé, ce n’est pas seulement « ne pas être malade » : c’est aussi se sentir bien dans sa tête et avec les autres.',
 c:C(`En 5e, on réfléchit à ce qui fait de chacun une personne <b>unique</b> : son corps, ses goûts, sa façon d’être. Chacun a le droit de développer sa personnalité <b>librement</b>, sans pression et sans discrimination, et de prendre soin de sa <b>santé</b> au sens large.`,
  [T('Sexe, genre, orientation : des notions différentes',`<p>Le <b>sexe</b> désigne les caractéristiques biologiques du corps. Le <b>genre</b> renvoie aux rôles, comportements et attentes que la société associe au fait d’être une fille ou un garçon, et à la façon dont une personne se ressent. L’<b>orientation sexuelle</b> désigne l’attirance affective et amoureuse envers d’autres personnes ; on en prend conscience progressivement. Ces diversités doivent être <b>respectées</b> : les discriminations sont interdites par la loi.</p>`),
   T('La santé, un bien-être complet',`<p>Selon l’Organisation mondiale de la santé (OMS), la santé est « un état complet de bien-être physique, mental et social ». On distingue un malaise, une douleur, un trouble, une maladie ; on sait demander de l’aide (infirmerie, médecin, adulte de confiance).</p><p>La diversité des apparences physiques n’empêche pas l’<b>égalité</b> : chacun a les mêmes droits et mérite le même respect.</p>`)],
  [{q:'Hugo aime la danse et des camarades lui disent que « ce n’est pas pour les garçons ». Analyse.',s:['C’est un stéréotype lié au genre.','Hugo a le droit de développer librement sa personnalité et ses goûts.','Se moquer de lui pour cette raison serait une discrimination ; il peut en parler à un adulte.']}],
  ['Je distingue sexe, genre et orientation sexuelle.','Je respecte la diversité de chacun.','Je connais la définition de la santé de l’OMS.','Je sais demander de l’aide quand je ne vais pas bien.'],
  ['Confondre sexe et genre.','Penser que les apparences physiques justifient des inégalités.','Croire que la santé, c’est seulement ne pas être malade.'],
  ['Sexe, genre, orientation : trois notions.','Santé = bien-être physique, mental et social.','Diversité, égalité, non-discrimination.']),
 g:mix([pairs([['le sexe','les caractéristiques biologiques du corps'],['le genre','les rôles et attentes que la société associe au fait d’être une fille ou un garçon'],['l’orientation sexuelle','l’attirance affective et amoureuse envers d’autres personnes'],['la santé (selon l’OMS)','un état complet de bien-être physique, mental et social']],{q:'Que désigne %s ?',rq:'Quelle notion correspond à : %s ?'}),2],
  [bank([
   ['Selon l’OMS, la santé est…','un état complet de bien-être physique, mental et social',['seulement l’absence de maladie','le fait de faire du sport','le fait d’être grand'],'C’est une définition large.'],
   ['Que signifie OMS ?','Organisation mondiale de la santé',['Office des médecins scolaires','Organisation des maladies saisonnières','Ordre mondial du sport'],'Agence des Nations unies pour la santé.'],
   ['« Ce sport n’est pas pour les filles » est…','un stéréotype de genre',['une règle sportive','une loi','un fait scientifique'],'Chacun peut pratiquer l’activité qu’il aime.'],
   ['La diversité des apparences physiques…','n’empêche pas l’égalité des droits',['justifie des inégalités','doit être cachée','est un problème'],'Chacun a les mêmes droits.'],
   ['Traiter quelqu’un moins bien à cause de son orientation sexuelle est…','une discrimination interdite par la loi',['autorisé','une opinion sans conséquence','une blague'],'L’article 225-1 du Code pénal définit les discriminations.',2],
   ['Tu ne te sens pas bien depuis plusieurs jours. Que faire ?','en parler à un adulte de confiance ou à l’infirmerie',['ne rien dire','attendre que ça passe sans en parler','demander sur un forum anonyme'],'Demander de l’aide fait partie de prendre soin de sa santé.'],
   ['Développer librement sa personnalité, c’est…','choisir ses goûts et sa façon d’être sans contrainte',['copier les autres','obéir aux stéréotypes','cacher qui on est'],'C’est l’objectif de 5e.'],
   ['Le bien-être « social » désigne…','le fait de se sentir bien avec les autres',['le nombre d’abonnés','le fait d’avoir de l’argent','le fait de parler fort'],'Les relations comptent pour la santé.',2],
   {tf:'Sexe et genre désignent exactement la même chose.',v:false,e:'Le sexe est biologique ; le genre renvoie aux rôles et attentes sociales.'},
   {tf:'Chacun a le droit au respect, quelles que soient ses différences.',v:true,e:'C’est un droit humain fondamental.'},
   ['Une douleur qui dure doit…','être signalée à un adulte ou un professionnel de santé',['être cachée','être ignorée','être soignée seul avec Internet'],'On sait se faire aider.',2],
   ['Les places des femmes et des hommes dans la société…','peuvent être influencées par des stéréotypes qu’on peut questionner',['sont fixées pour toujours','sont décidées par la nature seulement','ne changent jamais'],'Le programme invite à les analyser.',3]]),3])},

{id:'evars5b',name:'Choisir ses relations : consentement et refus',icon:'✋',domain:'Relations aux autres',
 refs:[AX2,OBJ('5e','Choisir ses relations ; connaître et assumer ses préférences, comprendre qu’elles peuvent évoluer'),EV],
 tip:'Le consentement, c’est un OUI libre, clair et qui peut changer. Le silence n’est pas un oui. Un « non » doit toujours être respecté.',
 c:C(`Choisir ses amis, accepter ou refuser une proposition, poser ses limites : en 5e, on apprend ce qui fait une relation <b>positive</b> et ce qu’est le <b>consentement</b>. Respecter l’<b>intimité</b> et l’<b>intégrité corporelle</b> de chacun est une règle absolue.`,
  [T('Relations positives, relations négatives',`<p>Une relation <b>positive</b> repose sur le respect, la confiance, la liberté et l’égalité. Une relation <b>négative</b> comporte pression, chantage, moqueries, contrôle ou violence. Chacun a droit à la <b>liberté</b> et au <b>respect</b> ; personne ne doit subir de discrimination.</p>`),
   T('Consentement et refus',`<p><b>Consentir</b>, c’est être d’accord, librement, sans pression. Le consentement peut se <b>retirer</b> à tout moment. Le <b>silence</b> ou l’absence de refus ne vaut pas accord. On apprend à exprimer son refus (« non », « stop ») et à <b>respecter</b> le refus de l’autre.</p><p>Tout acte de nature sexuelle non désiré constitue une <b>violence sexuelle</b>, interdite et punie par la loi. Sur Internet, des contenus sexuellement explicites, <b>interdits aux mineurs</b>, peuvent choquer et véhiculer des stéréotypes et de la violence : on ferme, on en parle à un adulte.</p>`)],
  [{q:'Sami veut emprunter le téléphone de Jade pour regarder ses photos. Jade hésite et ne répond pas. Que doit faire Sami ?',s:['Le silence n’est pas un accord.','Sami doit demander clairement et accepter la réponse.','Si Jade dit non, il respecte son refus sans insister.']}],
  ['Je repère ce qui rend une relation positive ou négative.','Je sais dire non et poser mes limites.','Je demande l’accord et je respecte un refus.','Je sais vers qui me tourner en cas de problème.'],
  ['Croire que « qui ne dit mot consent ».','Insister après un refus.','Penser qu’un accord donné une fois vaut pour toujours.'],
  ['Consentement : libre, clair, réversible.','Silence ≠ accord.','Violence : interdite et punie ; demander de l’aide.']),
 g:mix([d=>{const S=[['Léo dit « oui, avec plaisir » sans aucune pression.',true],['Maya ne répond pas et détourne le regard.',false],['Tom dit oui parce qu’on le menace de le rejeter du groupe.',false],['Inès avait dit oui, puis dit « finalement non ».',false],['Noé dit clairement « d’accord » et sourit, librement.',true],['Lou dit « je ne sais pas… ».',false],['Adam a accepté hier, mais aujourd’hui il dit « stop ».',false]];const [s,ok]=P(S);return ch(`Situation : ${s} Y a-t-il consentement ?`,ok?'Oui':'Non',[ok?'Non':'Oui'],{expl:ok?'L’accord est libre et clair.':'Le consentement doit être libre, clair et peut être retiré : ici il n’y a pas d’accord valable.',hint:'Libre, clair, et il peut changer.'});},3],
  [bank([
   ['Le consentement doit être…','libre et clair',['obtenu en insistant','supposé si la personne ne dit rien','donné une fois pour toujours'],'Sans pression, et exprimé clairement.'],
   ['Une personne qui a dit oui peut-elle changer d’avis ?','oui, à tout moment',['jamais','seulement le lendemain','seulement avec l’accord de l’autre'],'Le consentement est réversible.'],
   ['Le silence signifie-t-il un accord ?','pas du tout',['oui, toujours','oui, entre amis','oui, si on sourit'],'Seul un accord exprimé librement compte.'],
   ['Une relation où l’un contrôle le téléphone de l’autre est…','une relation négative',['une preuve d’amour','une relation positive','normale'],'Le contrôle est une forme de pression.'],
   ['Tout acte de nature sexuelle non désiré est…','une violence sexuelle punie par la loi',['un jeu','sans gravité','une marque d’affection'],'C’est ce que rappelle le programme.'],
   ['Tu tombes par hasard sur des images choquantes en ligne. Que faire ?','fermer la page et en parler à un adulte de confiance',['les partager','les garder secrètes à tout prix','les regarder encore'],'Ces contenus sont interdits aux mineurs.',2],
   ['Respecter un refus, c’est…','arrêter sans insister ni se moquer',['réessayer plus tard','se fâcher','menacer'],'Le non est une réponse complète.'],
   ['Une relation positive repose sur…','le respect, la confiance et l’égalité',['la peur','le chantage','le contrôle'],'Chacun s’y sent libre.'],
   {tf:'Dire non à un ami ne veut pas dire qu’on ne l’aime pas.',v:true,e:'On peut tenir à quelqu’un et poser ses limites.'},
   {tf:'Si quelqu’un insiste beaucoup, son « oui » final est un vrai consentement.',v:false,e:'Un accord obtenu sous pression n’est pas libre.',d:2},
   ['Les préférences de chacun…','peuvent évoluer avec le temps',['sont fixées pour la vie','doivent être les mêmes que celles du groupe','sont interdites'],'C’est l’objectif de 5e.',2],
   ['Les contenus sexuellement explicites sont…','interdits aux mineurs',['adaptés aux élèves de 5e','obligatoires au collège','sans aucun risque'],'Ils peuvent choquer et véhiculer des stéréotypes.',2]]),2])},

{id:'evars5c',name:'Vie publique, vie privée et cyberviolences',icon:'🛡️',domain:'Vie en société',
 refs:[AX3,OBJ('5e','Distinguer vie publique et vie privée, en réfléchissant à la signification de la liberté individuelle, en particulier sur les réseaux sociaux'),EV],
 tip:'Victime ou témoin de cyberviolence : ne pas répondre, garder des preuves, signaler, en parler (3018).',
 c:C(`Sur les réseaux sociaux, la frontière entre <b>vie privée</b> et <b>vie publique</b> est vite franchie : une photo, un message peuvent être vus par des centaines de personnes. La <b>liberté</b> de s’exprimer s’arrête là où commencent les <b>droits des autres</b> : dignité, vie privée, droit à l’image.`,
  [T('Droits de chacun',`<p>Chaque personne a des <b>droits humains</b> : droit à la <b>dignité</b>, au <b>respect de sa vie privée</b>, droit à l’<b>image</b>. Liberté, respect et égalité s’appliquent quels que soient le sexe, le genre ou l’orientation sexuelle. Les <b>discriminations</b> sont définies et punies par la loi (article 225-1 du Code pénal).</p>`),
   T('Cyberviolences sexistes et sexuelles',`<p>Insultes sexistes, rumeurs, diffusion de photos intimes, moqueries sur le corps : ce sont des <b>cyberviolences</b>. Elles ont des effets graves sur les victimes. Internet peut aussi exposer à des situations dangereuses ou à des infractions.</p><p>Réagir : écouter la victime avec empathie, la soutenir, <b>signaler</b> (plateforme, adulte, <b>3018</b>), ne jamais relayer. Chacun peut faire des <b>choix responsables</b>.</p>`)],
  [{q:'Une rumeur sexiste circule sur une élève dans un groupe en ligne. Tu es témoin. Que faire ?',s:['Ne pas relayer, ne pas réagir avec un « j’aime ».','Faire des captures d’écran et signaler le contenu.','Soutenir l’élève et prévenir un adulte de confiance ou contacter le 3018.']}],
  ['Je distingue ce qui est privé et ce qui est public.','Je connais les droits de chacun (dignité, vie privée, image).','Je reconnais une cyberviolence.','Je sais réagir : soutenir, signaler, en parler.'],
  ['Croire qu’un groupe « privé » garantit la confidentialité.','Penser que la liberté d’expression autorise les insultes.','Relayer une rumeur « sans y croire ».'],
  ['Vie privée ≠ vie publique.','Droits humains : dignité, vie privée, image.','Cyberviolence : soutenir, signaler, 3018.']),
 g:mix([sort({'Vie privée':['mes problèmes de santé','mon adresse','mes sentiments pour quelqu’un','les photos de ma famille'],'Vie publique':['un exposé présenté en classe','un article publié dans le journal du collège','un match du club ouvert au public']},{q:'« %s » relève plutôt de…'}),2],
  [bank([
   ['Une photo publiée dans un groupe « privé »…','peut être copiée et diffusée à d’autres',['reste forcément secrète','disparaît après 24 h dans tous les cas','ne peut pas être capturée'],'Une capture d’écran suffit.'],
   ['La liberté d’expression autorise-t-elle les insultes sexistes ?','non, elle s’arrête où commencent les droits des autres',['oui, toujours','oui, en ligne','oui, si c’est une blague'],'Les insultes et le harcèlement sont punis.'],
   ['Quel article du Code pénal définit les discriminations ?','l’article 225-1',['l’article 1er de la Constitution','l’article 12 du règlement intérieur','aucun'],'Le programme invite à le connaître.',2],
   ['Diffuser une photo intime de quelqu’un sans son accord est…','une cyberviolence grave punie par la loi',['une blague','autorisé entre élèves','sans conséquence'],'C’est une atteinte à sa vie privée et à sa dignité.'],
   ['Face à une victime de cyberviolence, une bonne réaction est…','l’écouter, la soutenir et signaler',['se moquer aussi','l’ignorer','lui dire que c’est sa faute'],'Écoute empathique et soutien solidaire.'],
   ['Le 3018 aide…','les victimes et témoins de harcèlement et de violences numériques',['à réserver un train','à commander un repas','à jouer en ligne'],'Gratuit, anonyme et confidentiel.'],
   ['Une victime de cyberviolence est-elle responsable de ce qui lui arrive ?','jamais',['oui, toujours','oui, si elle a publié une photo','oui, si elle a répondu'],'La responsabilité est celle de l’auteur.'],
   ['Le droit à la dignité signifie que…','chacun doit être traité avec respect',['on peut humilier quelqu’un en ligne','seuls les adultes ont des droits','on peut se moquer si c’est drôle'],'C’est un droit humain fondamental.'],
   {tf:'Relayer une rumeur, même sans y croire, contribue à la cyberviolence.',v:true,e:'Chaque partage amplifie la diffusion.'},
   {tf:'Ce qu’on publie sur un réseau social reste toujours privé.',v:false,e:'Le contenu peut devenir public.'},
   ['Garder des captures d’écran d’un harcèlement sert à…','avoir des preuves pour signaler',['se moquer plus tard','les publier','rien'],'Les preuves aident les adultes et les plateformes.',2],
   ['Faire un choix responsable sur les réseaux, c’est par exemple…','réfléchir avant de publier quelque chose sur quelqu’un',['tout partager','publier sous le coup de la colère','répondre aux insultes par des insultes'],'On pense aux conséquences.']]),2])}
]);

MQ.add('evars','4',[
{id:'evars4a',name:'Grandir, émotions et santé : s’informer et faire des choix',icon:'💬',domain:'Se connaître et grandir',
 refs:[AX1,OBJ('4e','Aborder la sexualité comme une réalité complexe pouvant faire intervenir le plaisir, l’amour, la reproduction, etc.'),EV],
 tip:'Pour une question de santé, on s’adresse à des sources fiables : infirmerie du collège, médecin, centres de santé sexuelle, sites publics.',
 c:C(`En 4e, le programme aborde la <b>sexualité</b> comme une réalité <b>complexe</b>, qui concerne à la fois le corps, les émotions et les relations, et qui peut faire intervenir l’amour, le plaisir, la reproduction. Chacun la vit selon un <b>cheminement personnel</b>, à son rythme. Savoir gérer ses émotions et savoir où s’informer aide à faire des choix responsables.`,
  [T('Une réalité aux multiples aspects',`<p>La sexualité a des dimensions physiques et psychologiques, personnelles et relationnelles ; elle fait l’objet de nombreuses <b>représentations</b> et de modèles sociaux. Elle se vit de façon singulière : il n’y a pas de « norme » à atteindre ni de calendrier à suivre. Il existe aussi des personnes <b>intersexes</b>, dont les caractéristiques biologiques ne correspondent pas entièrement aux définitions habituelles du masculin ou du féminin.</p><p>Reconnaître et <b>gérer ses émotions</b> aide à construire des relations de qualité et à prévenir les violences.</p>`),
   T('S’informer et être accompagné',`<p>Pour s’informer, se faire dépister ou soigner : l’<b>infirmerie</b> du collège, un médecin, les <b>centres de santé sexuelle</b>, les <b>CeGIDD</b> (centres gratuits d’information, de dépistage et de diagnostic). Exemples cités par le programme : vaccination contre les <b>papillomavirus humains</b> (HPV), douleurs gynécologiques, troubles du cycle menstruel, dépistage de l’endométriose.</p>`)],
  [{q:'Nour a des règles très douloureuses chaque mois et manque parfois les cours. Que lui conseiller ?',s:['Ce n’est pas une fatalité : des douleurs fortes nécessitent un avis médical.','Elle peut en parler à l’infirmier ou l’infirmière du collège et consulter un médecin.','Certains troubles (comme l’endométriose) peuvent être dépistés et pris en charge.']}],
  ['Je sais que la sexualité a plusieurs dimensions et se vit à son rythme.','Je reconnais mes émotions et j’apprends à les gérer.','Je connais les lieux où m’informer et me faire aider.','Je fais des choix responsables.'],
  ['Croire qu’il existe un âge ou un modèle « normal » pour tout le monde.','S’informer uniquement par des rumeurs ou des vidéos sans source.','Supporter une douleur sans consulter.'],
  ['Sexualité : réalité complexe, cheminement personnel.','Émotions : les reconnaître, les gérer.','Infirmerie, médecin, centres de santé sexuelle, CeGIDD.']),
 g:mix([bank([
   ['Que signifie CeGIDD ?','centre gratuit d’information, de dépistage et de diagnostic',['centre général des impôts','club des élèves du collège','centre de gestion des données'],'Ces centres sont gratuits.'],
   ['Contre quels virus existe un vaccin recommandé aux adolescentes et adolescents ?','les papillomavirus humains (HPV)',['le virus du rhume','tous les virus','aucun virus'],'Le programme cite cette vaccination.',2],
   ['Au collège, à qui poser une question de santé de façon confidentielle ?','à l’infirmier ou l’infirmière scolaire',['à un camarade sur un réseau social','au professeur de sport devant la classe','à personne'],'L’infirmerie est un lieu d’écoute et de conseil.'],
   ['La sexualité se vit…','selon un cheminement personnel, à son rythme',['au même âge pour tout le monde','selon un calendrier obligatoire','en copiant les autres'],'Il n’y a pas de norme à atteindre.'],
   ['Gérer ses émotions aide à…','construire des relations de qualité et prévenir les violences',['ne plus rien ressentir','dominer les autres','éviter tout le monde'],'C’est une compétence du programme.'],
   ['Une personne intersexe est une personne…','dont les caractéristiques biologiques ne correspondent pas entièrement aux définitions habituelles du masculin ou du féminin',['qui change de collège','qui n’a pas d’émotions','qui refuse les relations'],'Le programme demande de savoir que ces personnes existent.',2],
   ['Des douleurs de règles très fortes…','justifient une consultation médicale',['sont toujours normales','doivent être cachées','passent toujours seules'],'Un dépistage (par exemple de l’endométriose) peut être utile.'],
   ['Pour une information de santé fiable en ligne, on privilégie…','les sites d’organismes publics de santé',['les rumeurs','les commentaires anonymes','les publicités'],'Les sources identifiées et sérieuses.'],
   {tf:'Il existe un âge précis auquel tout le monde doit vivre les mêmes expériences.',v:false,e:'Chacun suit son propre cheminement.'},
   {tf:'Les centres de santé sexuelle peuvent accueillir les jeunes.',v:true,e:'Ils informent, conseillent et proposent des dépistages.'},
   ['Faire un choix responsable pour sa santé, c’est…','s’informer à des sources fiables et demander conseil',['suivre l’avis du groupe sans réfléchir','ne jamais en parler','croire les rumeurs'],'On décide de façon éclairée.'],
   ['Reconnaître ses émotions, c’est d’abord…','savoir les nommer (joie, peur, colère, tristesse…)',['les cacher','les ignorer','les imposer aux autres'],'Nommer aide à mieux réagir.']]),3])},

{id:'evars4b',name:'Relations, consentement, images et prévention',icon:'🔐',domain:'Relations aux autres',
 refs:[AX2,OBJ('4e','Développer une compréhension critique et respectueuse des relations interpersonnelles et des enjeux associés à la sexualité ; favoriser des choix responsables et protecteurs en matière de santé sexuelle et relationnelle'),EV],
 tip:'Une image intime partagée peut échapper à tout contrôle : on n’en demande pas, on n’en envoie pas, on ne la transfère jamais. En cas de problème : 3018.',
 c:C(`Une relation se fonde sur l’<b>échange</b>, le <b>partage</b>, la <b>réciprocité</b> et le <b>consentement</b>, qui est lié à la <b>liberté</b>. Les réseaux sociaux influencent les relations et l’estime de soi. En 4e, on apprend aussi à prendre des décisions protectrices pour sa santé et celle des autres, et à savoir où trouver de l’aide.`,
  [T('Le regard des autres et les images',`<p>Être sous le regard des autres (« j’aime », commentaires) peut aider à s’affirmer, mais aussi <b>nuire</b> à l’estime de soi. La diffusion d’images de soi ou des autres comporte des risques : une image peut être copiée, détournée, utilisée pour faire pression. Diffuser des contenus intimes sans accord (<b>pornodivulgation</b>) est une infraction grave. L’<b>emprise</b> est un mécanisme par lequel une personne en contrôle une autre (chantage, isolement, menaces).</p>`),
   T('Se protéger et protéger les autres',`<p>Le programme demande de comprendre l’importance de décisions favorables à sa santé : la décision d’avoir ou non une relation sexuelle appartient à chacun ; la <b>prévention des infections sexuellement transmissibles</b> (IST) repose notamment sur le <b>préservatif</b> et le dépistage ; des <b>moyens de contraception</b> existent pour prévenir les grossesses non prévues, et l’<b>IVG</b> est un droit. Pour s’informer : infirmerie, médecin, centres de santé sexuelle.</p><p>Aide en cas de violence : adulte de confiance, <b>3018</b> (violences numériques), <b>119</b> (enfance en danger).</p>`)],
  [{q:'Un garçon demande à une élève de lui envoyer une photo intime « pour prouver qu’elle l’aime ». Analyse.',s:['C’est une pression : l’amour ne se prouve pas par une photo.','Une image envoyée peut être diffusée sans contrôle ; la diffuser sans accord est une infraction.','Elle peut refuser, en parler à un adulte de confiance ou au 3018.']}],
  ['J’analyse ce qui fait une relation réciproque et respectueuse.','Je repère pressions, chantage et emprise.','Je connais les risques liés à la diffusion d’images.','Je sais où m’informer et demander de l’aide.'],
  ['Croire qu’une photo envoyée en privé reste privée.','Penser que « liker » un contenu humiliant est anodin.','Ignorer qu’il existe des lieux d’information gratuits et confidentiels.'],
  ['Relation : échange, réciprocité, consentement.','Images intimes : ne pas demander, ne pas envoyer, ne pas transférer.','Prévention : préservatif, dépistage, contraception ; aide : 3018, 119.']),
 g:mix([bank([
   ['Une relation réciproque, c’est une relation où…','chacun donne et reçoit, de façon équilibrée',['une seule personne décide','l’un contrôle l’autre','on ne se parle pas'],'La réciprocité est au cœur d’une relation saine.'],
   ['L’emprise, c’est…','le contrôle exercé par une personne sur une autre (pressions, chantage, isolement)',['une preuve d’amour','un conseil d’ami','une activité sportive'],'Le programme demande de la repérer.'],
   ['Diffuser une image intime de quelqu’un sans son accord est…','une infraction grave',['autorisé si on est en couple','sans conséquence','une blague'],'On parle de pornodivulgation.'],
   ['Quel moyen protège des infections sexuellement transmissibles ?','le préservatif',['la pilule seule','un vaccin contre la grippe','la crème solaire'],'Le préservatif protège des IST ; le dépistage est aussi important.',2],
   ['Que signifie IST ?','infection sexuellement transmissible',['institut des sciences et techniques','intervention scolaire temporaire','information sur la santé du travail'],'Elle se transmet lors de relations sexuelles.'],
   ['La décision d’avoir ou non une relation sexuelle…','appartient à chacun, librement',['est décidée par le groupe','doit suivre la pression des amis','est imposée par l’autre'],'C’est un choix personnel et libre.',2],
   ['Le « regard des autres » sur les réseaux sociaux peut…','aider à s’affirmer, mais aussi nuire à l’estime de soi',['seulement faire du bien','seulement faire du mal','n’avoir aucun effet'],'Il faut savoir s’en protéger.'],
   ['Une personne te menace de diffuser une photo si tu n’obéis pas. Tu…','ne cèdes pas, gardes des preuves et contactes un adulte ou le 3018',['obéis','envoies d’autres photos','ne dis rien'],'C’est du chantage, une infraction.'],
   ['Où peut-on s’informer gratuitement sur la contraception et la prévention ?','à l’infirmerie, chez un médecin, dans un centre de santé sexuelle',['sur des forums anonymes uniquement','nulle part','auprès de publicités'],'Ces lieux sont confidentiels.',2],
   {tf:'Une photo envoyée en message privé peut être diffusée sans que l’on puisse l’empêcher.',v:true,e:'Elle peut être capturée et partagée.'},
   {tf:'Le consentement n’a rien à voir avec la liberté.',v:false,e:'Le programme lie le consentement à la liberté de chacun.'},
   ['Le 119 est le numéro…','de l’enfance en danger',['des renseignements','de la météo','d’un réseau social'],'Gratuit, 24 h sur 24.']]),3])},

{id:'evars4c',name:'Normes, stéréotypes et images dans les médias',icon:'📺',domain:'Vie en société',
 refs:[AX3,OBJ('4e','Étudier des représentations de la sexualité dans l’espace public et en interroger la dimension égalitaire ou inégalitaire'),EV],
 tip:'Face à une publicité ou une image : qui la produit, dans quel but, et quelle image des femmes et des hommes donne-t-elle ?',
 c:C(`Publicités, clips, séries, réseaux sociaux : les médias diffusent des <b>représentations</b> des corps et des relations. Certaines sont <b>égalitaires</b>, d’autres véhiculent des <b>stéréotypes</b> et une <b>marchandisation</b> des corps. En 4e, on apprend à les décrypter avec un esprit critique.`,
  [T('Normes, modèles et stéréotypes',`<p>Une <b>norme sociale</b> indique ce qui est attendu dans un groupe ; un <b>modèle</b> sert d’exemple ; un <b>stéréotype</b> est une image figée. Ils ont des effets : <b>intégration</b> ou <b>exclusion</b>, socialisation, normalisation. On repère les représentations égalitaires ou inégalitaires (femmes/hommes ; majorités/minorités).</p><p>La publicité utilise souvent des corps retouchés ou sexualisés pour vendre : c’est la <b>marchandisation des corps</b>.</p>`),
   T('Contenus interdits aux mineurs',`<p>La <b>pornographie</b> est interdite aux mineurs par le <b>Code pénal</b> : les sites ont l’obligation de vérifier l’âge. Elle représente de manière faussement réaliste et stéréotypée des actes dépourvus de dimension affective, souvent violents ; elle ne montre pas des relations réelles. Les réseaux de prostitution utilisent les réseaux sociaux pour recruter : la prostitution a des conséquences graves sur la santé des victimes. En cas de contact suspect : en parler immédiatement à un adulte, 119.</p>`)],
  [{q:'Une publicité pour un parfum montre un corps retouché qui n’a aucun rapport avec le produit. Analyse.',s:['Le corps est utilisé pour attirer l’attention : c’est une marchandisation du corps.','La retouche impose un modèle irréaliste.','On peut se demander si la représentation est égalitaire et quel stéréotype elle transmet.']}],
  ['J’identifie qui produit l’image et dans quel but.','Je repère stéréotypes et retouches.','Je juge si la représentation est égalitaire.','Je sais que certains contenus sont interdits aux mineurs et pourquoi.'],
  ['Prendre une image publicitaire pour la réalité.','Croire que les contenus pornographiques montrent des relations réelles.','Répondre à un inconnu qui propose de l’argent contre des photos.'],
  ['Norme, modèle, stéréotype : effets d’intégration ou d’exclusion.','Marchandisation des corps.','Pornographie : interdite aux mineurs, image fausse et violente.']),
 g:mix([bank([
   ['La marchandisation du corps, c’est…','utiliser le corps comme un objet pour vendre',['faire du sport','prendre soin de sa santé','acheter des vêtements'],'Fréquent dans la publicité.'],
   ['Une image publicitaire retouchée…','présente un modèle irréaliste',['montre la réalité','est interdite','n’a aucun effet'],'Elle peut influencer l’image de soi.'],
   ['Pourquoi la pornographie est-elle interdite aux mineurs ?','elle montre une image fausse, stéréotypée et souvent violente, qui peut choquer',['parce qu’elle est trop chère','parce qu’elle est en anglais','elle n’est pas interdite'],'L’interdiction est inscrite dans le Code pénal.',2],
   ['Un inconnu en ligne propose de l’argent ou des cadeaux contre des photos. Que faire ?','ne pas répondre, garder des preuves et prévenir un adulte',['accepter','envoyer une photo floue','donner son adresse'],'Les réseaux d’exploitation recrutent ainsi.',2],
   ['Une norme sociale peut avoir pour effet…','d’intégrer certaines personnes et d’en exclure d’autres',['de rendre tout le monde égal automatiquement','rien','de supprimer les règles'],'Il faut en interroger les effets.'],
   ['Une représentation égalitaire des femmes et des hommes…','leur donne une place et des rôles comparables',['montre les femmes seulement à la maison','réserve les métiers techniques aux hommes','présente un seul modèle de corps'],'On compare les rôles attribués.'],
   ['Pour analyser une publicité, on se demande d’abord…','qui la produit et dans quel but',['si elle est en couleur','combien elle a coûté','qui l’a regardée'],'Le but est souvent de vendre.'],
   ['La prostitution a, pour les victimes,…','des conséquences graves sur la santé',['aucune conséquence','des effets positifs','un intérêt scolaire'],'Le programme demande d’en prendre conscience.',3],
   {tf:'Les contenus pornographiques montrent des relations telles qu’elles sont dans la réalité.',v:false,e:'Ils sont faussement réalistes et stéréotypés.'},
   {tf:'Les sites pornographiques ont l’obligation légale de vérifier l’âge des visiteurs.',v:true,e:'L’accès est interdit aux mineurs.',d:2},
   ['« Dans ce clip, seules les filles sont jugées sur leur apparence. » C’est une représentation…','inégalitaire',['égalitaire','neutre','scientifique'],'Les rôles ne sont pas comparables.'],
   ['Un stéréotype est…','une image figée et simplifiée d’un groupe',['une loi','une statistique exacte','une œuvre d’art'],'Il peut conduire à l’exclusion.']]),3])}
]);

MQ.add('evars','3',[
{id:'evars3a',name:'Bonheur, émotions et maîtrise de soi',icon:'💡',domain:'Se connaître et grandir',
 refs:[AX1,OBJ('3e','Interroger les liens entre bonheur, émotions et sexualité'),EV],
 tip:'Ressentir une émotion ou une envie n’oblige jamais à agir : entre ce que l’on ressent et ce que l’on fait, il y a la réflexion et le choix.',
 c:C(`En 3e, on réfléchit aux liens entre <b>bonheur</b>, <b>émotions</b> et sexualité, et à la notion de <b>santé sexuelle</b>. Une idée centrale : on peut ressentir des émotions ou des envies fortes, mais nos <b>comportements</b>, eux, peuvent être réfléchis et maîtrisés. C’est là que se joue notre liberté et le respect des autres.`,
  [T('Ressentir et agir',`<p>Le <b>désir</b> renvoie à l’imagination, aux émotions, aux envies ; le <b>comportement</b> correspond à des actions qui peuvent être <b>réfléchies et contrôlées</b>. Un désir peut ne pas toujours être satisfait, et ce n’est pas un drame. Apprendre à maîtriser ses impulsions et ses émotions protège soi-même et les autres.</p><p>Il faut aussi garder un regard critique sur les représentations fausses ou déformées (autour de la « performance », de la « première fois ») et sur les idées préconçues liées au genre ou à l’orientation sexuelle.</p>`),
   T('Le corps de chacun lui appartient',`<p>Les <b>mutilations sexuelles féminines</b> sont une atteinte grave aux droits fondamentaux : elles sont <b>interdites et sévèrement punies par la loi</b> en France, et aucune tradition ne peut les justifier. Une jeune fille menacée peut être protégée : en parler à un adulte de confiance, à l’infirmerie, au <b>119</b>.</p>`)],
  [{q:'Un élève dit : « Quand on est en colère, on ne peut pas s’empêcher de frapper. » Qu’en penser ?',s:['La colère est une émotion normale.','Le comportement (frapper) peut être réfléchi et contrôlé : on peut s’éloigner, respirer, en parler.','Maîtriser ses impulsions protège les autres et soi-même.']}],
  ['Je distingue émotion ou envie, et comportement.','J’apprends des stratégies pour maîtriser mes impulsions.','J’ai un regard critique sur les représentations déformées.','Je sais que le corps de chacun lui appartient et que la loi le protège.'],
  ['Croire qu’une envie oblige à agir.','Croire aux images de « performance » des médias.','Penser qu’une tradition peut justifier une violence.'],
  ['Désir ≠ comportement : on choisit ses actes.','Santé sexuelle et bien-être.','Mutilations sexuelles : interdites ; aide : 119.']),
 g:mix([sort({'Une émotion ou une envie':['ressentir de la colère','être attiré par quelqu’un','avoir peur','être jaloux'],'Un comportement (que l’on peut choisir)':['crier sur quelqu’un','envoyer un message','s’éloigner pour se calmer','insister après un refus']},{q:'« %s » est…'}),3],
  [bank([
   ['Ressentir une envie oblige-t-il à agir ?','pas du tout : le comportement peut être réfléchi et contrôlé',['oui, toujours','oui, si l’envie est forte','oui, si les autres sont d’accord'],'C’est une idée centrale du programme de 3e.'],
   ['Un désir qui n’est pas satisfait…','fait partie de la vie et doit être accepté',['donne le droit d’insister','justifie la colère','est anormal'],'Le désir peut ne pas toujours être assouvi.'],
   ['Une stratégie pour maîtriser une impulsion de colère :','s’éloigner, respirer, en parler plus tard',['frapper un mur','insulter','envoyer un message tout de suite'],'Prendre du recul permet de choisir sa réaction.'],
   ['Les mutilations sexuelles féminines sont, en France,…','interdites et sévèrement punies par la loi',['autorisées si c’est une tradition','sans conséquences','un choix médical'],'Aucune tradition ne peut les justifier.'],
   ['Les images de « performance » diffusées dans certains médias…','donnent des représentations fausses ou déformées',['reflètent la réalité','sont des modèles à suivre','sont scientifiques'],'Le programme invite à les analyser de façon critique.',2],
   ['La santé sexuelle fait partie…','de la santé globale et du bien-être',['uniquement de la médecine d’urgence','de la vie des adultes seulement','des matières à option'],'La santé est physique, mentale et sociale.',2],
   ['Une jeune fille craint d’être emmenée à l’étranger pour subir une mutilation. Qui peut l’aider ?','un adulte de confiance, l’infirmerie, le 119',['personne','seulement ses amis','un forum anonyme'],'Elle peut être protégée.',2],
   {tf:'On est toujours responsable de ses actes, même quand on ressent une émotion forte.',v:true,e:'Les comportements peuvent être réfléchis et contrôlés.'},
   {tf:'Une tradition peut justifier une atteinte au corps d’une personne.',v:false,e:'Le respect des droits fondamentaux s’impose.'},
   ['Nommer ses émotions aide à…','mieux les comprendre et mieux réagir',['les faire disparaître','dominer les autres','éviter toute relation'],'Première étape pour les gérer.']]),2])},

{id:'evars3b',name:'Relation réciproque et égalitaire, risques et protection',icon:'⚖️',domain:'Relations aux autres',
 refs:[AX2,OBJ('3e','Construire une relation réciproque et égalitaire ; savoir reconnaître et caractériser des contextes de danger et de vulnérabilité'),EV],
 tip:'« Elle a dit non mais elle voulait dire oui » : FAUX. Un non est un non. Et une personne sous l’effet d’alcool ou de drogue n’est pas en état de consentir.',
 c:C(`Une relation saine est <b>réciproque</b> et <b>égalitaire</b> : chacun peut dire oui, dire non, changer d’avis. En 3e, on apprend à caractériser le <b>consentement</b>, à reconnaître les <b>situations de danger</b> (emprise, violences, substances) et à connaître les moyens de <b>se protéger</b> et de protéger les autres.`,
  [T('Partage, consentement, réciprocité',`<p>Être d’accord ou pas, ne pas avoir les mêmes envies au même moment : la relation demande d’accepter la <b>frustration</b> et de <b>respecter un refus</b>. Le consentement doit être <b>donné et obtenu</b>, clairement. Certaines situations empêchent de consentir librement : <b>alcool ou drogues</b> (substances psychoactives, qui modifient le raisonnement), <b>emprise</b>, rapport de domination ou de pouvoir, <b>soumission chimique</b>.</p><p>Les violences peuvent être physiques, psychologiques, verbales, sexistes, sexuelles, numériques, dans le couple ou non. Une victime n’est jamais responsable ; elle a besoin de soutien. Le <b>mariage forcé</b> est une atteinte aux droits humains : la loi protège les victimes.</p>`),
   T('Prévention et ressources',`<p>Le programme demande de connaître : la réduction des risques d’<b>IST</b> (dont le <b>VIH</b>) : préservatif, <b>dépistage</b>, traitements préventifs (PrEP) et d’urgence après une exposition (TPE), vaccination contre les <b>HPV</b> ; la prévention des grossesses non prévues : <b>contraception</b>, tests de grossesse ; le droit à l’<b>IVG</b>, garanti par la loi et inscrit dans la Constitution depuis 2024.</p><p>Ressources : infirmerie, médecin, centres de santé sexuelle, CeGIDD, numéro vert national « Sexualités, contraception, IVG » (0 800 08 11 11), <b>119</b>.</p>`)],
  [{q:'Analyse la phrase : « Il n’a pas dit qu’il n’était pas d’accord, donc il était d’accord. »',s:['L’absence de refus ne vaut pas consentement.','Le consentement doit être exprimé clairement et librement.','En cas de doute, on demande, et on respecte la réponse.']}],
  ['Je caractérise le consentement (donné, obtenu, libre, réversible).','J’identifie les situations qui empêchent de consentir.','Je reconnais l’emprise et les violences.','Je connais les moyens de prévention et les ressources d’aide.'],
  ['Croire qu’un « non » peut vouloir dire « oui ».','Penser qu’une personne ivre peut consentir librement.','Croire que la victime est en partie responsable.'],
  ['Relation réciproque et égalitaire.','Pas de consentement sous l’effet de substances, sous emprise ou sous la contrainte.','Prévention : préservatif, dépistage, contraception ; ressources : CeGIDD, 0 800 08 11 11, 119.']),
 g:mix([d=>{const S=[['« Elle a dit non, mais elle voulait dire oui. »',false],['« Il a dit oui clairement, sans aucune pression. »',true],['« Elle n’a rien dit, donc c’était d’accord. »',false],['« Il avait trop bu pour répondre, mais il n’a pas refusé. »',false],['« Elle était d’accord hier, donc c’est toujours d’accord. »',false],['« Ils ont tous les deux exprimé leur accord, librement. »',true]];const [s,ok]=P(S);return ch(`${s} Cette phrase décrit-elle un consentement valable ?`,ok?'Oui':'Non',[ok?'Non':'Oui'],{expl:ok?'Accord exprimé, libre et clair.':'Un consentement doit être exprimé librement et clairement, peut être retiré, et ne peut pas être donné sous l’effet de substances.',hint:'Libre, clair, actuel.'});},3],
  [bank([
   ['Une personne sous l’effet de l’alcool ou de drogues…','n’est pas en état de consentir librement',['consent toujours','consent si elle ne dit rien','consent si elle sourit'],'Les substances psychoactives modifient le raisonnement.'],
   ['La soumission chimique, c’est…','administrer une substance à quelqu’un à son insu pour le rendre vulnérable',['un cours de chimie','un médicament prescrit','un jeu'],'C’est un crime.',2],
   ['Que signifie VIH ?','virus de l’immunodéficience humaine',['vaccin international hebdomadaire','virus inoffensif humain','vitamine indispensable'],'Il peut provoquer le sida s’il n’est pas traité.',2],
   ['Quel moyen protège à la fois des IST et des grossesses non prévues ?','le préservatif',['la pilule','le dépistage','le vaccin HPV'],'La pilule ne protège pas des IST.',2],
   ['Le mariage forcé est…','une atteinte aux droits humains, interdite par la loi',['une tradition acceptable','un choix libre','autorisé à 15 ans'],'La loi protège les victimes.'],
   ['Une victime de violences est-elle responsable de ce qu’elle a subi ?','jamais',['parfois','si elle connaissait l’auteur','si elle n’a pas crié'],'Elle a besoin de soutien.'],
   ['Depuis 2024, la liberté de recourir à l’IVG est…','inscrite dans la Constitution',['interdite','réservée aux adultes de plus de 30 ans','décidée par les parents seulement'],'Réforme constitutionnelle de mars 2024.',3],
   ['Le numéro vert national « Sexualités, contraception, IVG » est…','gratuit et anonyme',['payant','réservé aux médecins','une application de jeu'],'0 800 08 11 11.',2],
   ['L’emprise se caractérise notamment par…','le contrôle, l’isolement et la peur',['l’égalité','la confiance réciproque','la liberté de chacun'],'Elle empêche de consentir librement.'],
   {tf:'Accepter un refus fait partie d’une relation égalitaire.',v:true,e:'Chacun peut dire non.'},
   {tf:'La pilule contraceptive protège des IST.',v:false,e:'Seul le préservatif protège des IST.',d:2},
   ['Les CeGIDD proposent…','information, dépistage et diagnostic gratuits',['des cours de conduite','des stages de sport','des consultations payantes uniquement'],'Centres gratuits d’information, de dépistage et de diagnostic.']]),3])},

{id:'evars3c',name:'Droits humains, égalité et lutte contre les violences',icon:'🕊️',domain:'Vie en société',
 refs:[AX3,OBJ('3e','Inscrire la sexualité dans la définition et le respect des droits humains'),EV],
 tip:'Toute discrimination fondée sur le sexe, l’orientation sexuelle, l’identité de genre ou l’état de santé est interdite (article 225-1 du Code pénal).',
 c:C(`La sexualité s’inscrit dans le respect des <b>droits humains</b> : égalité entre les femmes et les hommes, égalité entre les orientations sexuelles, droit à la différence. En 3e, on étudie comment les lois ont évolué, on apprend à reconnaître les violences et les discriminations, et à agir pour les prévenir.`,
  [T('Droits, devoirs et évolution des lois',`<p>Le <b>Code pénal</b> (article 225-1) interdit les discriminations fondées notamment sur le sexe, l’orientation sexuelle, l’identité de genre ou l’état de santé. Les lois ont évolué : en France, la <b>loi du 4 août 1982</b> a mis fin à la pénalisation spécifique de l’homosexualité ; le <b>17 mai 1990</b>, l’OMS a retiré l’homosexualité de la liste des maladies (le 17 mai est devenu la journée mondiale contre l’homophobie et la transphobie).</p>`),
   T('Reconnaître les violences et agir',`<p><b>Violences sexistes et sexuelles</b> (y compris l’<b>inceste</b>), <b>homophobie</b>, stigmatisation : il faut savoir les reconnaître. Les victimes n’en sont <b>jamais responsables</b>. Chacun peut jouer un rôle actif : écouter, soutenir, signaler, ne pas rire ni relayer. Numéros d’urgence : <b>119</b> pour les mineurs (enfance en danger), <b>17</b> (police), <b>3018</b> (violences numériques).</p>`)],
  [{q:'Dans un club de sport, un joueur est moqué à cause de son orientation sexuelle supposée. Comment agir ?',s:['C’est de l’homophobie, une discrimination interdite par la loi.','Ne pas rire ni relayer ; soutenir la personne visée.','Signaler à l’entraîneur ou à un adulte de confiance ; en cas de violences, 119 ou 17.']}],
  ['Je connais les principaux droits et l’article 225-1 du Code pénal.','Je situe quelques évolutions de la loi.','Je reconnais violences, stigmatisation et discriminations.','Je sais agir : soutenir, signaler, demander de l’aide.'],
  ['Croire qu’une moquerie homophobe est « juste une blague ».','Penser que la victime a provoqué la violence.','Ignorer les numéros d’urgence.'],
  ['Égalité femmes-hommes et entre orientations.','Loi du 4 août 1982 ; OMS 17 mai 1990.','Victimes jamais responsables ; 119, 17, 3018.']),
 g:mix([bank([
   ['Quel article du Code pénal définit les discriminations ?','l’article 225-1',['l’article 1er du Code civil','l’article 49.3','l’article 7 du règlement intérieur'],'Il cite notamment le sexe, l’orientation sexuelle, l’identité de genre, l’état de santé.'],
   ['En quelle année la loi française a-t-elle mis fin à la pénalisation spécifique de l’homosexualité ?','1982',['1945','1968','2013'],'Loi du 4 août 1982.',2],
   ['Le 17 mai 1990, l’OMS a…','retiré l’homosexualité de la liste des maladies',['créé le 119','inventé le vaccin HPV','fondé l’ONU'],'Le 17 mai est la journée mondiale contre l’homophobie et la transphobie.',2],
   ['L’homophobie est…','une discrimination ou une violence envers les personnes homosexuelles',['une opinion autorisée','une maladie','un sport'],'Elle est punie par la loi.'],
   ['Quel numéro appeler quand un mineur est en danger ?','le 119',['le 3615','le 0 800 00 00 00','le 112 seulement pour les adultes'],'Gratuit, 24 h sur 24, 7 jours sur 7.'],
   ['L’inceste est…','une violence sexuelle commise au sein de la famille, interdite par la loi',['autorisé dans certaines familles','une tradition','un conflit sans gravité'],'Les victimes peuvent être aidées (119).',2],
   ['Face à une discrimination dont tu es témoin, tu peux…','soutenir la victime et signaler',['rire avec les autres','filmer et publier','ne rien faire'],'Chacun peut jouer un rôle actif.'],
   ['L’égalité entre les femmes et les hommes est…','un principe inscrit dans la loi',['une option','une opinion','un vœu sans valeur'],'C’est un droit fondamental.'],
   {tf:'Les victimes de violences sexuelles en sont parfois responsables.',v:false,e:'Elles ne sont jamais responsables.'},
   {tf:'Le droit à la différence fait partie des principes liés aux droits humains.',v:true,e:'C’est l’un des principes cités par le programme.'},
   ['Le 17 est le numéro…','de la police (police secours)',['du SAMU','des pompiers','de l’enfance en danger'],'15 : SAMU ; 18 : pompiers ; 119 : enfance en danger.'],
   ['La stigmatisation, c’est…','marquer quelqu’un d’une image négative à cause d’une caractéristique',['féliciter quelqu’un','aider une victime','voter une loi'],'Elle conduit à l’exclusion.',3]]),3])}
]);

MQ.add('orientation','6',[
{id:'orientation6a',name:'Découvrir ses goûts, ses forces et ses façons d’apprendre',icon:'🔎',domain:'Connaissance de soi',
 refs:[AV,'Parcours Avenir — objectif « se connaître et développer ses compétences »'],
 tip:'Un goût n’est pas une note : on peut aimer une matière et avoir encore des progrès à faire, ou l’inverse.',
 c:C(`Le <b>parcours Avenir</b> commence dès la 6e : avant de penser « métier », on apprend à se connaître. Quelles matières j’aime ? Comment j’apprends le mieux ? Quelles sont mes <b>qualités</b> ? Se connaître aide à progresser et, plus tard, à choisir.`,
  [T('Goûts et qualités',`<p>Un <b>goût</b> est ce qu’on aime faire (lire, construire, dessiner, calculer, bouger, aider). Une <b>qualité</b> est une façon d’être qui aide dans beaucoup de situations (curiosité, persévérance, soin, sens de l’écoute, créativité). On peut avoir des goûts différents de ses résultats scolaires du moment : un goût peut se développer.</p>`),
   T('Comment j’apprends',`<p>Chacun a des <b>façons d’apprendre</b> qui lui conviennent mieux : lire, écouter, manipuler, schématiser, répéter à voix haute. Identifier ce qui fonctionne pour soi aide à mieux travailler. Le parcours Avenir se construit tout au long du collège et du lycée, grâce à des <b>temps dédiés</b>, des rencontres et des visites.</p>`)],
  [{q:'Léo n’est pas le meilleur en sciences, mais il adore observer les insectes du jardin. Que lui dire ?',s:['Un goût n’est pas une note : il peut aimer les sciences et encore progresser.','Ce goût est une piste à explorer, pas une case à cocher tout de suite.','Le parcours Avenir sert justement à explorer ces pistes sur plusieurs années.']}],
  ['Je repère ce que j’aime faire.','J’identifie mes qualités.','Je découvre comment j’apprends le mieux.','Je comprends que le parcours Avenir dure tout le collège.'],
  ['Confondre un goût et une note.','Croire qu’il faut déjà savoir son métier en 6e.','Penser que ses façons d’apprendre ne peuvent pas évoluer.'],
  ['Goût ≠ résultat scolaire.','Qualités : curiosité, persévérance, écoute…','Parcours Avenir : sur plusieurs années.']),
 g:mix([sort({'Un goût':['aimer dessiner','aimer lire des romans','aimer bricoler','aimer faire du sport'],'Une qualité':['la persévérance','la curiosité','le sens de l’écoute','le soin apporté au travail']},{q:'« %s » est…'}),2],
  [bank([
   ['Un goût, c’est…','ce qu’on aime faire',['une note obtenue en classe','un métier obligatoire','une qualité uniquement'],'Il peut évoluer avec le temps.'],
   ['Avoir une note moyenne dans une matière qu’on aime signifie…','qu’on peut aimer une matière et encore progresser',['qu’il faut abandonner ce goût','qu’on n’a aucune qualité','qu’on doit changer de matière'],'Le goût et le résultat sont deux choses différentes.'],
   ['Le parcours Avenir commence…','dès la 6e',['seulement en 3e','seulement au lycée','après le brevet'],'Il se construit sur plusieurs années.'],
   ['Une façon d’apprendre qui convient à un élève…','peut être différente de celle d’un autre élève',['est la même pour tout le monde','n’a aucune importance','ne peut jamais changer'],'Chacun trouve ce qui lui convient.'],
   ['La persévérance est…','une qualité utile dans beaucoup de situations',['un métier','une matière scolaire','un diplôme'],'Elle aide à continuer malgré les difficultés.'],
   {tf:'On peut découvrir de nouveaux goûts au fil du collège.',v:true,e:'Les goûts évoluent avec les expériences.'},
   {tf:'Il faut absolument connaître son futur métier en 6e.',v:false,e:'Le parcours Avenir laisse le temps d’explorer.'}]),3])},

{id:'orientation6b',name:'Découvrir la diversité des métiers',icon:'🧑‍🔧',domain:'Monde professionnel',
 refs:[AV,ONI,'Parcours Avenir — objectif « découvrir le monde économique et professionnel »'],
 tip:'Derrière chaque objet ou service du quotidien (un pain, une appli, un pont), il y a souvent plusieurs métiers différents qui ont travaillé ensemble.',
 c:C(`Il existe des <b>milliers de métiers</b>, souvent mal connus. Les découvrir, c’est élargir ses idées et éviter de se limiter aux métiers « qu’on connaît déjà » (souvent ceux de ses parents ou vus à la télévision).`,
  [T('Des métiers dans tous les secteurs',`<p>Un <b>secteur d’activité</b> regroupe des métiers autour d’un même domaine : <b>agriculture</b>, <b>industrie</b>, <b>commerce</b>, <b>santé</b>, <b>éducation</b>, <b>numérique</b>, <b>artisanat</b>, <b>culture</b>, <b>services</b>… Un même objet (un pain, un vélo, une application) fait intervenir plusieurs métiers successifs ou associés.</p>`),
   T('Où s’informer',`<p>L’<b>Onisep</b> est l’organisme public qui informe sur les métiers et les formations (fiches métiers, vidéos). On peut aussi observer les métiers autour de soi, poser des questions aux adultes, visiter des lieux de travail. Il ne faut pas limiter ses idées de métiers à ceux déjà connus dans son entourage.</p>`)],
  [{q:'Pour fabriquer et vendre une baguette de pain, quels métiers interviennent ?',s:['L’agriculteur ou l’agricultrice qui cultive le blé.','Le meunier ou la meunière qui transforme le blé en farine.','Le boulanger ou la boulangère qui fabrique et vend le pain.']}],
  ['Je repère plusieurs secteurs d’activité.','Je comprends qu’un objet fait intervenir plusieurs métiers.','Je sais utiliser l’Onisep pour m’informer.','J’élargis mes idées au-delà des métiers déjà connus.'],
  ['Croire qu’il n’existe que les métiers vus à la télévision.','Penser qu’un seul métier suffit à fabriquer un objet complexe.','Ignorer les ressources comme l’Onisep.'],
  ['Secteurs d’activité variés.','Un objet = plusieurs métiers.','Onisep : fiches métiers, vidéos.']),
 g:mix([sort({'Secteur de la santé':['infirmier ou infirmière','médecin','aide-soignant ou aide-soignante'],'Secteur du numérique':['développeur ou développeuse informatique','technicien ou technicienne réseau','graphiste'],'Secteur de l’artisanat':['boulanger ou boulangère','menuisier ou menuisière','couturier ou couturière']},{q:'Le métier « %s » appartient plutôt au secteur…'}),2],
  [bank([
   ['L’Onisep est…','l’organisme public qui informe sur les métiers et les formations',['un réseau social','une entreprise privée de recrutement','un diplôme'],'Ses fiches métiers sont une bonne source d’information.'],
   ['Un secteur d’activité regroupe…','des métiers autour d’un même domaine',['une seule personne','un seul diplôme','un seul lieu de travail'],'Exemples : santé, numérique, artisanat.'],
   ['Pour fabriquer une application mobile, quels métiers interviennent souvent ?','développeur ou développeuse, graphiste, testeur ou testeuse',['seulement un informaticien','seulement un vendeur','personne, c’est automatique'],'Plusieurs métiers coopèrent.'],
   ['Pourquoi est-il utile de découvrir des métiers peu connus ?','pour élargir ses idées avant de choisir plus tard',['ce n’est jamais utile','pour les éviter à tout prix','pour décider tout de suite de son métier'],'Plus on connaît de métiers, plus on a de pistes.'],
   {tf:'Il existe seulement une dizaine de métiers différents.',v:false,e:'Il en existe des milliers.'},
   {tf:'Un même objet du quotidien peut faire intervenir plusieurs métiers.',v:true,e:'Exemple : le pain (agriculteur, meunier, boulanger).'}]),3])},

{id:'orientation6c',name:'Comprendre les matières et compétences scolaires',icon:'📘',domain:'Parcours scolaire',
 refs:[AV,'Parcours Avenir — objectif « comprendre le monde économique et professionnel »','Socle commun de connaissances, de compétences et de culture'],
 tip:'Une compétence scolaire (comme « argumenter » ou « mesurer ») peut servir dans plusieurs matières ET dans plusieurs métiers plus tard.',
 c:C(`Les matières étudiées au collège (français, mathématiques, sciences, langues, arts…) ne sont pas cloisonnées : elles développent des <b>compétences</b> transférables, utiles dans la vie et pour de nombreux métiers.`,
  [T('Matières et compétences',`<p>Une <b>compétence</b> est une capacité à faire quelque chose (calculer, argumenter, s’exprimer à l’oral, travailler en équipe, créer). Le <b>socle commun</b> définit ce que tout élève doit maîtriser en fin de scolarité obligatoire. Une même compétence (par exemple « argumenter ») se retravaille en français, en histoire-géographie, en sciences.</p>`),
   T('Des liens avec les métiers',`<p>Calculer sert en gestion, en architecture, en informatique. S’exprimer à l’oral sert dans presque tous les métiers. Travailler en équipe sert dans le sport, la santé, l’industrie. Comprendre ce lien aide à donner du sens aux apprentissages scolaires.</p>`)],
  [{q:'À quoi peut servir, plus tard, la compétence « argumenter » travaillée en français et en histoire ?',s:['Convaincre un client ou un collègue.','Défendre un projet devant un jury.','Expliquer un choix dans de nombreux métiers (avocat, commerçant, ingénieur…).']}],
  ['Je repère les compétences travaillées dans chaque matière.','Je comprends qu’une compétence sert dans plusieurs matières.','Je fais le lien entre compétences scolaires et métiers.','Je donne du sens à ce que j’apprends.'],
  ['Croire qu’une matière ne sert à rien plus tard.','Penser que les compétences restent enfermées dans une seule matière.','Ignorer le lien entre apprentissages et vie professionnelle.'],
  ['Compétence = capacité transférable.','Socle commun.','Lien matières ↔ métiers.']),
 g:mix([pairs([['argumenter','défendre une idée avec des raisons'],['mesurer','déterminer une grandeur avec un instrument ou un calcul'],['travailler en équipe','coopérer avec d’autres pour atteindre un but commun'],['s’exprimer à l’oral','communiquer clairement devant un public'],['résoudre un problème','chercher une solution à une situation nouvelle']],{q:'La compétence « %s » consiste à…',rq:'Quelle compétence correspond à : %s ?'}),2],
  [bank([
   ['Le socle commun définit…','ce que tout élève doit maîtriser en fin de scolarité obligatoire',['les notes du brevet','la liste des métiers','les horaires de cours'],'Il regroupe connaissances, compétences et culture.'],
   ['La compétence « argumenter » se travaille…','dans plusieurs matières (français, histoire, sciences…)',['uniquement en français','uniquement en histoire','dans aucune matière'],'Elle est transférable.'],
   ['« Travailler en équipe » peut être utile…','dans le sport, la santé, l’industrie et bien d’autres métiers',['seulement au collège','seulement en EPS','nulle part après le collège'],'C’est une compétence très recherchée.'],
   {tf:'Une compétence apprise dans une matière peut être utile ailleurs.',v:true,e:'C’est le principe de la compétence transférable.'},
   {tf:'Chaque matière développe des compétences totalement isolées des autres.',v:false,e:'Beaucoup de compétences sont communes à plusieurs matières.'}]),2])},

{id:'orientation6d',name:'Interroger un professionnel : préparer ses questions',icon:'🎙️',domain:'Exploration',
 refs:[AV,'Parcours Avenir — objectif « découvrir le monde économique et professionnel »'],
 tip:'Une bonne question commence souvent par « Comment… », « Pourquoi… » ou « Qu’est-ce qui… » : elle invite à une réponse développée, pas juste « oui » ou « non ».',
 c:C(`Rencontrer un <b>professionnel</b> (lors d’une visite, d’un forum des métiers, d’une intervention en classe) permet d’en apprendre beaucoup — à condition de <b>préparer ses questions</b> à l’avance.`,
  [T('Préparer la rencontre',`<p>Avant la rencontre : se renseigner un peu sur le métier, noter ce qu’on voudrait savoir. Pendant : écouter attentivement, poser ses questions avec <b>politesse</b>, prendre des notes. Après : relire ses notes, en retenir l’essentiel.</p>`),
   T('Des questions utiles',`<p>Des questions ouvertes donnent de meilleures réponses : « Qu’est-ce qui vous plaît dans ce métier ? », « Comment se déroule une journée de travail ? », « Quelles études avez-vous suivies ? », « Quelles difficultés rencontrez-vous ? ». Éviter les questions trop fermées (qui n’appellent qu’un oui ou un non).</p>`)],
  [{q:'Une infirmière vient parler de son métier en classe. Prépare trois questions à lui poser.',s:['« Comment se déroule une journée de travail pour vous ? »','« Qu’est-ce qui vous a donné envie de faire ce métier ? »','« Quelles études avez-vous suivies après le collège ? »']}],
  ['Je me renseigne un peu avant la rencontre.','Je prépare des questions ouvertes.','J’écoute et je prends des notes.','Je relis mes notes après.'],
  ['Poser seulement des questions fermées (oui/non).','Ne rien préparer avant la rencontre.','Ne pas écouter les réponses des autres élèves.'],
  ['Préparer avant, écouter pendant, retenir après.','Questions ouvertes : Comment, Pourquoi, Qu’est-ce qui…','Politesse envers l’intervenant.']),
 g:mix([sort({'Question ouverte (donne une réponse développée)':['Comment se déroule votre journée de travail ?','Pourquoi avez-vous choisi ce métier ?','Qu’est-ce qui est le plus difficile dans votre travail ?'],'Question fermée (réponse oui/non)':['Aimez-vous votre métier ?','Travaillez-vous le week-end ?','Avez-vous fait des études longues ?']},{q:'« %s » est une…'}),2],
  [bank([
   ['Une question ouverte permet d’obtenir…','une réponse développée et détaillée',['seulement oui ou non','aucune réponse','une réponse fermée'],'Elle commence souvent par Comment, Pourquoi, Qu’est-ce qui.'],
   ['Avant de rencontrer un professionnel, il est utile de…','se renseigner un peu sur son métier',['ne rien préparer','venir sans aucune idée','poser des questions sur sa vie privée'],'Cela permet de poser de meilleures questions.'],
   ['Pendant la rencontre, il est utile de…','prendre des notes',['parler sans écouter','jouer sur son téléphone','interrompre sans arrêt'],'Pour se souvenir des informations utiles.'],
   {tf:'« Travaillez-vous le week-end ? » est une question fermée.',v:true,e:'Elle appelle une réponse oui ou non.'},
   {tf:'Il est inutile de préparer des questions avant une rencontre avec un professionnel.',v:false,e:'Préparer ses questions permet d’en apprendre davantage.'},
   ['« Qu’est-ce qui vous plaît dans votre métier ? » est une question…','ouverte, qui invite à une réponse développée',['fermée','impolie','sans intérêt'],'Elle commence par « qu’est-ce qui ».'],
   ['« Travaillez-vous le samedi ? » est une question…','fermée, qui appelle un oui ou un non',['ouverte','impossible à poser','la meilleure question possible'],'Elle n’invite pas à développer.'],
   ['Prendre des notes pendant une rencontre permet…','de se souvenir des réponses plus tard',['de perdre du temps','de déranger l’intervenant','de remplacer l’écoute'],'On peut écouter et noter l’essentiel en même temps.'],
   ['Avant de poser une question personnelle (salaire, etc.) à un professionnel, il vaut mieux…','réfléchir si la question est adaptée au contexte',['la poser sans réfléchir','l’éviter à tout prix','la poser en premier obligatoirement'],'Certaines questions demandent plus de tact.']]),2])},

{id:'orientation6e',name:'Construire un premier carnet de découvertes',icon:'📔',domain:'Projet',
 refs:[AV,'Parcours Avenir — traçabilité des découvertes de l’élève'],
 tip:'Un carnet de découvertes n’a pas besoin d’être long : une phrase ou deux après chaque découverte suffisent, si elles sont sincères.',
 c:C(`Tout au long du collège, le parcours Avenir invite à garder une <b>trace</b> de ce que l’on découvre : métiers rencontrés, visites, ce que l’on a aimé ou pas. Ce <b>carnet de découvertes</b> aide à se souvenir et à voir son évolution.`,
  [T('Pourquoi garder une trace',`<p>On oublie vite ses impressions. Noter quelques lignes après chaque découverte (une visite, une rencontre, une vidéo sur un métier) permet de s’en souvenir plus tard, par exemple en 3e pour préparer un stage ou choisir une orientation.</p>`),
   T('Que noter',`<p>La date, ce qui a été découvert, ce qu’on a aimé ou pas, une question qu’on se pose encore. Pas besoin d’être long : quelques phrases honnêtes suffisent. Ce carnet appartient à l’élève et l’accompagne durant tout le collège.</p>`)],
  [{q:'Après une visite à la ferme du village, que noter dans son carnet ?',s:['La date et le lieu de la visite.','Ce qui a plu (être au contact des animaux) ou moins plu (se lever tôt).','Une question qu’on se pose encore (Quelles études pour devenir agriculteur ?).']}],
  ['Je note la date et ce qui a été découvert.','Je note ce que j’ai aimé ou moins aimé.','Je note les questions que je me pose encore.','Je relis mon carnet régulièrement.'],
  ['Attendre la 3e pour commencer à noter ses découvertes.','Écrire des phrases non sincères pour « faire bien ».','Ne jamais relire son carnet.'],
  ['Trace écrite après chaque découverte.','Date, impression, question en suspens.','Carnet utile jusqu’en 3e.']),
 g:mix([bank([
  ['À quoi sert un carnet de découvertes ?','à garder une trace de ce qu’on découvre sur les métiers et les formations',['à noter ses notes de contrôle','à remplacer le cahier de textes','à rien'],'Il aide à se souvenir et à préparer l’avenir.'],
  ['Que peut-on noter après une rencontre avec un professionnel ?','ce qu’on a appris et ce qu’on a aimé ou pas',['uniquement la météo du jour','rien, ce n’est pas nécessaire','le nom de tous les élèves présents'],'Des impressions sincères et utiles.'],
  ['Le carnet de découvertes est utile…','tout au long du collège, jusqu’en 3e',['seulement le jour où on l’écrit','seulement en 6e','jamais'],'Il permet de voir son évolution.'],
  {tf:'Il faut écrire de longues pages après chaque découverte.',v:false,e:'Quelques phrases sincères suffisent.'},
  {tf:'Relire son carnet plus tard peut aider à se souvenir de ses impressions.',v:true,e:'La mémoire s’efface vite sans trace écrite.'},
  ['Un carnet de découvertes appartient…','à l’élève, qui le garde tout au long du collège',['uniquement au professeur','à l’administration du collège','à personne en particulier'],'Il accompagne le parcours de l’élève.'],
  ['Noter une question qu’on se pose encore après une visite permet…','de la retrouver plus tard pour y répondre',['de l’oublier plus vite','de perdre du temps','de ne jamais progresser'],'C’est un bon réflexe pour avancer.'],
  ['Le carnet de découvertes peut contenir des notes sur…','des visites, des rencontres ou des vidéos sur des métiers',['uniquement les notes de contrôle','uniquement des dessins','rien de précis'],'Toute découverte utile peut y être notée.'],
  {tf:'Un carnet de découvertes doit obligatoirement être tenu sur un cahier spécial fourni par le collège.',v:false,e:'Il peut prendre différentes formes (cahier, fichier numérique…).'},
  ['À quel moment peut-on commencer un carnet de découvertes ?','dès la 6e',['seulement en 3e','seulement au lycée','jamais avant le brevet'],'Plus tôt on commence, plus le carnet est riche.'],
  ['Le carnet de découvertes sert notamment à préparer…','le stage de 3e et le projet d’orientation',['uniquement les évaluations de sciences','uniquement les sorties scolaires','rien en particulier'],'Il nourrit la réflexion sur l’orientation.'],
  ['Écrire des phrases sincères dans son carnet, même négatives (« je n’ai pas aimé »), est…','utile pour bien se connaître',['interdit','inutile','une erreur à toujours éviter'],'Ce qui n’a pas plu est aussi une information utile.']]),2])}
]);

MQ.add('orientation','5',[
{id:'orientation5a',name:'Identifier ses centres d’intérêt et compétences',icon:'🧭',domain:'Connaissance de soi',
 refs:[AV,'Parcours Avenir — objectif « se connaître et développer ses compétences »'],
 tip:'Un centre d’intérêt (ce qui m’attire) et une compétence (ce que je sais faire) sont deux choses différentes : on peut être attiré par un domaine sans encore savoir le faire.',
 c:C(`En 5e, on approfondit la connaissance de soi : quels sont mes <b>centres d’intérêt</b> ? Quelles <b>compétences</b> ai-je déjà développées, à l’école ou ailleurs (club, famille, loisirs) ?`,
  [T('Centres d’intérêt et compétences',`<p>Un <b>centre d’intérêt</b> est un domaine qui attire l’attention et donne envie d’en savoir plus (les animaux, la musique, l’informatique, le sport, l’aide aux autres…). Une <b>compétence</b> est une capacité déjà développée, par exemple savoir organiser un match, s’occuper d’un petit frère, réparer un objet, parler une langue.</p>`),
   T('Des compétences hors de l’école',`<p>On développe des compétences au collège, mais aussi dans un club, une association, en famille, pendant les loisirs. Ces compétences comptent aussi : elles peuvent être valorisées plus tard (CV, entretien de stage).</p>`)],
  [{q:'Enzo joue au football en club depuis 5 ans et aide son petit frère à faire ses devoirs. Quelles compétences a-t-il développées ?',s:['Le travail en équipe et le respect des règles, grâce au football.','La patience et la pédagogie, en aidant son petit frère.','Ces compétences, développées hors de l’école, comptent aussi.']}],
  ['Je distingue centre d’intérêt et compétence.','Je repère mes compétences développées à l’école.','Je repère mes compétences développées hors de l’école (club, famille, loisirs).','Je comprends que ces compétences peuvent être valorisées plus tard.'],
  ['Croire que seules les compétences scolaires comptent.','Confondre être attiré par un domaine et savoir déjà le faire.','Sous-estimer ce qu’on a appris en dehors de l’école.'],
  ['Centre d’intérêt ≠ compétence.','Compétences développées à l’école et hors école.','Valorisation possible plus tard (CV, entretien).']),
 g:mix([sort({'Centre d’intérêt':['être attiré par les animaux','aimer la musique','être passionné d’informatique'],'Compétence déjà développée':['savoir arbitrer un match','savoir s’occuper d’un enfant plus jeune','savoir réparer un vélo','parler une langue étrangère']},{q:'« %s » est plutôt…'}),2],
  [bank([
   ['Un centre d’intérêt, c’est…','un domaine qui attire et donne envie d’en savoir plus',['une capacité déjà maîtrisée','une note scolaire','un diplôme'],'On peut s’intéresser à un domaine sans encore le maîtriser.'],
   ['Une compétence acquise en dehors de l’école (par exemple au club de théâtre) compte-t-elle ?','oui, elle peut être valorisée plus tard',['non, seule l’école compte','non, ce n’est jamais utile','oui, mais seulement pour le sport'],'Toutes les expériences comptent.'],
   ['Aider régulièrement un proche à faire ses devoirs développe notamment…','la patience et la pédagogie',['uniquement la fatigue','aucune compétence','seulement de la chance'],'Ce sont des compétences transférables.'],
   {tf:'On peut être intéressé par un métier sans encore savoir le faire.',v:true,e:'Le centre d’intérêt précède souvent la compétence.'},
   {tf:'Seules les compétences apprises en classe comptent pour l’orientation.',v:false,e:'Les compétences acquises en club, en famille ou en loisir comptent aussi.'},
   ['Savoir organiser un tournoi entre amis développe notamment…','l’organisation et le travail en équipe',['uniquement la chance','aucune compétence','la paresse'],'Organiser demande des compétences transférables.'],
   ['Un centre d’intérêt peut-il évoluer au fil du temps ?','oui, il peut changer avec les expériences',['non, il est fixé une fois pour toutes','non, c’est interdit','non, cela n’arrive jamais'],'Les goûts évoluent naturellement.'],
   ['Pourquoi est-il utile d’identifier ses compétences en 5e ?','pour mieux se connaître avant de réfléchir à son orientation',['pour obtenir une meilleure note','pour impressionner les professeurs','ce n’est pas utile'],'Cela prépare les étapes suivantes du parcours Avenir.'],
   {tf:'Apprendre une langue étrangère en dehors de l’école est une compétence qui ne compte pas.',v:false,e:'Toute compétence acquise, même hors école, peut être valorisée.'}]),2])},

{id:'orientation5b',name:'Explorer secteurs d’activité et métiers',icon:'🏗️',domain:'Monde professionnel',
 refs:[AV,ONI,'Parcours Avenir — objectif « découvrir le monde économique et professionnel »'],
 tip:'Un même métier peut s’exercer dans des lieux très différents : un cuisinier peut travailler dans un restaurant, un hôpital, une cantine scolaire ou sur un bateau.',
 c:C(`En 5e, on explore plus en détail quelques <b>secteurs d’activité</b> : qu’est-ce qui s’y fait, quels métiers y travaillent, quelles <b>études</b> y mènent ? L’objectif n’est pas de choisir déjà, mais d’élargir sa connaissance du monde professionnel.`,
  [T('Secteurs et filières',`<p>Chaque secteur (santé, numérique, bâtiment, agriculture, transport, culture…) regroupe des métiers très variés, qui demandent des formations différentes : <b>CAP</b>, <b>bac professionnel</b>, <b>bac général ou technologique</b>, puis études supérieures. Un même métier peut s’exercer dans des lieux très différents.</p>`),
   T('Diplômes et voies de formation',`<p>Le <b>CAP</b> (certificat d’aptitude professionnelle) prépare directement à un métier. Le <b>bac professionnel</b> allie enseignement général et professionnel. Le <b>bac général</b> et le <b>bac technologique</b> mènent surtout à des études supérieures. Il n’y a pas de voie « supérieure » à une autre : chacune mène à des métiers différents.</p>`)],
  [{q:'Dans le secteur du bâtiment, quels métiers peut-on trouver ?',s:['Maçon ou maçonne, électricien ou électricienne, architecte.','Certains s’apprennent par un CAP, d’autres par des études plus longues.','Les métiers d’un même secteur demandent des formations différentes.']}],
  ['Je découvre plusieurs secteurs d’activité en détail.','Je comprends qu’un métier peut s’exercer dans différents lieux.','Je distingue CAP, bac professionnel, bac général et technologique.','Je comprends qu’aucune voie n’est supérieure à une autre.'],
  ['Croire qu’un secteur ne contient qu’un seul métier.','Penser qu’une seule voie de formation « vaut mieux » que les autres.','Limiter un métier à un seul lieu d’exercice.'],
  ['Secteurs variés, métiers nombreux.','CAP, bac pro, bac général/technologique.','Pas de voie supérieure à une autre.']),
 g:mix([pairs([['CAP','certificat d’aptitude professionnelle, qui prépare directement à un métier'],['bac professionnel','diplôme alliant enseignement général et professionnel'],['bac général','diplôme qui mène surtout à des études supérieures générales'],['bac technologique','diplôme qui mène surtout à des études supérieures technologiques']],{q:'Le %s est…',rq:'Quel diplôme correspond à : %s ?'}),2],
  [bank([
   ['Le CAP prépare…','directement à l’exercice d’un métier',['uniquement à des études longues','à aucun métier','à devenir médecin'],'C’est une voie professionnelle courte.'],
   ['Un cuisinier peut travailler…','dans un restaurant, un hôpital, une cantine ou ailleurs',['uniquement dans un restaurant','uniquement chez lui','nulle part'],'Un métier s’exerce dans des lieux variés.'],
   ['Le bac général mène surtout…','à des études supérieures générales',['directement à un métier manuel uniquement','à l’arrêt des études','à un diplôme unique obligatoire'],'Il prépare à la poursuite d’études.'],
   {tf:'Une voie professionnelle (CAP, bac pro) vaut moins qu’une voie générale.',v:false,e:'Chaque voie mène à des métiers différents, aucune n’est supérieure.'},
   {tf:'Un même secteur d’activité regroupe des métiers qui demandent des formations différentes.',v:true,e:'Exemple : le bâtiment regroupe CAP et études d’ingénieur.'},
   ['Un même métier peut-il s’exercer dans des lieux très différents ?','oui, par exemple un cuisinier en restaurant, en hôpital ou en cantine',['non, toujours au même endroit','non, c’est interdit','non, cela n’existe pas'],'Les lieux d’exercice varient beaucoup.'],
   ['Explorer plusieurs secteurs d’activité en 5e permet…','d’élargir sa connaissance du monde professionnel sans avoir à choisir tout de suite',['de choisir définitivement son métier','de perdre du temps inutilement','de remplacer le stage de 3e'],'C’est une étape du parcours Avenir.']]),2])},

{id:'orientation5c',name:'Découvrir les voies de formation',icon:'🛣️',domain:'Parcours scolaire',
 refs:[AV,'Code de l’éducation — organisation du système scolaire français (collège, lycée, enseignement supérieur)'],
 tip:'Après la 3e, il existe plusieurs voies : elles ne sont pas classées « meilleure » ou « moins bonne », mais adaptées à des projets différents.',
 c:C(`Le système scolaire français propose, après le collège, plusieurs <b>voies de formation</b>. En 5e, il est utile de commencer à connaître leurs grandes lignes, sans avoir à choisir dès maintenant.`,
  [T('Après la 3e : trois grandes voies',`<p>La <b>voie générale et technologique</b> (lycée général et technologique) prépare surtout à des études supérieures. La <b>voie professionnelle</b> (lycée professionnel) prépare à un métier, avec des périodes de stage. L’<b>apprentissage</b> permet d’alterner formation en centre et travail en entreprise, avec un contrat et une rémunération.</p>`),
   T('Après le lycée',`<p>Après le bac : université, <b>BTS</b> (brevet de technicien supérieur), <b>BUT</b> (bachelor universitaire de technologie), écoles spécialisées, classes préparatoires… De nombreux parcours existent, avec des durées différentes (2, 3, 5 ans ou plus).</p>`)],
  [{q:'Après la 3e, Nina veut apprendre un métier tout en étant payée. Quelle voie choisir ?',s:['L’apprentissage, qui alterne formation et travail en entreprise.','Elle signe un contrat avec une entreprise et perçoit une rémunération.','C’est une voie différente, mais pas « inférieure » au lycée général.']}],
  ['Je connais les trois grandes voies après la 3e.','Je sais ce qu’est l’apprentissage.','Je découvre quelques formations après le bac.','Je comprends qu’aucune voie n’est supérieure à une autre.'],
  ['Croire qu’il n’existe qu’une seule voie après la 3e.','Penser que l’apprentissage n’est pas rémunéré.','Juger une voie « moins bien » qu’une autre.'],
  ['Voie générale/technologique, professionnelle, apprentissage.','BTS, BUT, université après le bac.','Chaque voie a sa valeur.']),
 g:mix([bank([
  ['L’apprentissage permet…','d’alterner formation en centre et travail en entreprise, avec un contrat',['de ne faire que de la théorie','de ne jamais travailler en entreprise','d’être exclu du système scolaire'],'L’apprenti est rémunéré.'],
  ['Le lycée professionnel prépare…','à un métier, avec des périodes de stage',['uniquement à l’université','à aucun métier','à devenir obligatoirement ingénieur'],'On y obtient un bac professionnel ou un CAP.'],
  ['Le BTS est…','un diplôme obtenu après le bac, en 2 ans en général',['un diplôme du collège','obtenu avant la 3e','un diplôme universitaire de 5 ans obligatoire'],'Brevet de technicien supérieur.',2],
  ['Une classe préparatoire se situe…','après le bac, pour préparer un concours d’entrée en grande école',['avant la 6e','pendant la 3e','à la place du bac'],'C’est une voie exigeante après le lycée.',2],
  ['Un diplôme universitaire (licence, master) se prépare…','à l’université, après le bac',['au collège','avant la 3e','en CAP uniquement'],'Les études universitaires durent plusieurs années.'],
  ['Le BUT est…','un diplôme universitaire de technologie, obtenu en 3 ans après le bac',['un diplôme de collège','un synonyme de CAP','un concours'],'Bachelor universitaire de technologie.',2],
  {tf:'Toutes les voies après la 3e ont la même valeur, même si elles sont différentes.',v:true,e:'Chaque voie correspond à un projet différent.'},
  {tf:'L’apprentissage signifie travailler gratuitement en entreprise.',v:false,e:'L’apprenti perçoit une rémunération.'},
  ['Combien de temps dure en général un BTS ?','2 ans après le bac',['1 an','5 ans','10 ans'],'Brevet de technicien supérieur.'],
  ['Combien de temps dure en général un BUT ?','3 ans après le bac',['1 an','6 mois','8 ans'],'Bachelor universitaire de technologie.'],
  ['Une classe préparatoire prépare principalement…','à intégrer une grande école après concours',['à passer le brevet','à entrer en apprentissage','à redoubler la 3e'],'C’est une voie après le bac.',2],
  ['Choisir entre ces voies en 5e est-il déjà obligatoire ?','non, ce n’est pas encore le moment de choisir définitivement',['oui, il faut décider dès la 5e','oui, sinon on redouble','oui, sous peine de sanction'],'Le parcours Avenir laisse le temps d’explorer.']]),2])},

{id:'orientation5d',name:'Combattre les stéréotypes liés aux métiers',icon:'⚖️',domain:'Égalité',
 refs:[AV,'Parcours Avenir — objectif « élaborer son projet d’orientation scolaire et professionnelle »'],
 tip:'Un métier n’a pas de sexe : ce qui compte, ce sont les compétences et l’envie, pas le fait d’être une fille ou un garçon.',
 c:C(`Certains métiers sont encore perçus comme « réservés » aux femmes ou aux hommes : ce sont des <b>stéréotypes</b>. Les reconnaître permet de ne pas limiter ses choix et de respecter les choix des autres.`,
  [T('Des stéréotypes fréquents',`<p>« Les métiers du bâtiment, c’est pour les hommes » ; « les métiers du soin, c’est pour les femmes » : ces idées sont des <b>stéréotypes de genre</b>, pas des faits. Dans la réalité, des femmes sont ingénieures, pompières, pilotes ; des hommes sont infirmiers, sages-femmes (on dit aussi « maïeuticien »), assistants maternels.</p>`),
   T('Pourquoi ça compte',`<p>Les stéréotypes peuvent décourager quelqu’un de choisir un métier qui lui plairait vraiment. Il existe des <b>inégalités</b> persistantes (métiers très majoritairement occupés par un seul sexe, écarts de salaire) que des politiques publiques cherchent à réduire. Chacun doit pouvoir choisir un métier selon ses goûts et ses compétences, pas selon son sexe.</p>`)],
  [{q:'Un garçon de 5e dit qu’il aimerait devenir sage-femme (« maïeuticien »), mais craint les moqueries. Que lui répondre ?',s:['Ce métier n’est réservé à aucun sexe.','Des hommes exercent déjà ce métier.','Choisir un métier selon ses goûts est un droit, pas un sujet de moquerie.']}],
  ['Je reconnais un stéréotype lié à un métier.','Je connais des contre-exemples (femmes ingénieures, hommes infirmiers…).','Je comprends l’enjeu de l’égalité professionnelle.','Je respecte le choix de métier de chacun.'],
  ['Croire qu’un métier est réservé à un sexe.','Se moquer d’un choix de métier « atypique ».','Ignorer que des inégalités professionnelles existent encore.'],
  ['Stéréotype de genre ≠ réalité.','Contre-exemples nombreux.','Choix de métier : goûts et compétences, pas sexe.']),
 g:mix([sort({'Stéréotype (idée fausse)':['« ce métier est pour les hommes »','« les filles ne peuvent pas être pompières »','« un homme ne peut pas être infirmier »'],'Réalité (fait vérifiable)':['des femmes sont pilotes d’avion','des hommes sont sages-femmes','des femmes dirigent des entreprises du bâtiment']},{q:'« %s » relève de…'}),2],
  [bank([
   ['« Ce métier est réservé aux hommes » est…','un stéréotype de genre, pas un fait',['une loi','une vérité scientifique','une règle du collège'],'Les compétences ne dépendent pas du sexe.'],
   ['Une sage-femme peut être…','une femme ou un homme',['uniquement une femme','uniquement un homme','un robot'],'On dit aussi « maïeuticien » pour un homme exerçant ce métier.'],
   ['Pourquoi les stéréotypes de métier sont-ils un problème ?','ils peuvent décourager quelqu’un de choisir un métier qui lui plairait',['ils n’ont aucune conséquence','ils aident à bien choisir','ils sont toujours vrais'],'Ils limitent les choix.'],
   {tf:'Un métier devrait se choisir selon les goûts et les compétences, pas selon le sexe.',v:true,e:'C’est le principe de l’égalité professionnelle.'},
   {tf:'Il n’existe aucune femme ingénieure ou pilote.',v:false,e:'C’est un stéréotype faux : ces métiers sont exercés par des femmes.'},
   ['Des écarts de salaire entre femmes et hommes existent-ils encore aujourd’hui ?','oui, et des politiques publiques cherchent à les réduire',['non, ils ont totalement disparu','non, cela n’a jamais existé','oui, mais ce n’est pas un problème'],'C’est une inégalité encore réelle.',2],
   ['Choisir un métier selon son sexe plutôt que selon ses goûts est…','une conséquence des stéréotypes',['une bonne méthode','obligatoire','sans aucun lien avec les stéréotypes'],'Les stéréotypes limitent les choix.'],
   ['Respecter le choix de métier « atypique » d’un camarade, c’est…','ne pas le juger ni le moquer',['se moquer gentiment','l’encourager à changer d’avis','l’ignorer'],'Chacun choisit selon ses goûts et compétences.']]),2])},

{id:'orientation5e',name:'Présenter un métier ou un secteur',icon:'🗣️',domain:'Projet',
 refs:[AV,ONI,'Parcours Avenir — objectif « élaborer son projet d’orientation scolaire et professionnelle »'],
 tip:'Une bonne présentation répond à trois questions simples : en quoi consiste ce métier ? quelles études y mènent ? pourquoi m’intéresse-t-il (ou pas) ?',
 c:C(`Choisir un métier ou un secteur, faire des recherches, puis le <b>présenter</b> à la classe : c’est un exercice classique du parcours Avenir, qui permet de s’entraîner à chercher l’information et à la communiquer.`,
  [T('Faire une recherche structurée',`<p>Pour présenter un métier, on cherche : en quoi il consiste (missions, lieu de travail), quelles études ou formations y mènent, quelles qualités ou compétences il demande, et éventuellement quel est le salaire moyen. Les sources fiables : <b>Onisep</b>, sites d’organismes professionnels, témoignages de professionnels.</p>`),
   T('Présenter clairement',`<p>Une présentation réussie est <b>organisée</b> (introduction, parties, conclusion), <b>illustrée</b> (image, exemple concret) et <b>sourcée</b>. On peut expliquer pourquoi ce métier intéresse (ou n’intéresse pas) celui qui le présente, sans obligation de s’y projeter personnellement.</p>`)],
  [{q:'Présente en trois points le métier de vétérinaire.',s:['En quoi il consiste : soigner les animaux, conseiller les propriétaires.','Études : plusieurs années après le bac, concours d’entrée en école vétérinaire.','Qualités utiles : sens de l’observation, résistance, empathie envers les animaux.']}],
  ['Je cherche des informations fiables (Onisep…).','J’organise ma présentation (missions, études, qualités).','J’illustre avec un exemple concret.','Je cite mes sources.'],
  ['Présenter un métier sans avoir vérifié les informations.','Oublier de parler des études nécessaires.','Ne citer aucune source.'],
  ['Missions, études, qualités requises.','Présentation organisée et sourcée.','Onisep : source fiable.']),
 g:mix([bank([
  ['Pour présenter un métier, il est utile de chercher…','les missions, les études nécessaires et les qualités requises',['uniquement le salaire','uniquement le nom du métier','rien, on improvise'],'Une recherche structurée donne une présentation complète.'],
  ['Quelle source est fiable pour une recherche sur les métiers ?','l’Onisep',['un réseau social sans auteur','une rumeur','une publicité'],'C’est l’organisme public de référence.'],
  ['Une présentation réussie est…','organisée, illustrée et sourcée',['improvisée sans préparation','sans aucune source','la plus longue possible'],'La clarté compte plus que la longueur.'],
  {tf:'Présenter un métier oblige à vouloir l’exercer plus tard.',v:false,e:'On peut présenter un métier par simple curiosité ou pour s’informer.'},
  {tf:'Il est utile de citer ses sources quand on présente un métier.',v:true,e:'Cela montre le sérieux de la recherche.'},
  ['Que peut-on utiliser pour illustrer une présentation de métier ?','une image ou un exemple concret',['rien, le texte seul suffit toujours','uniquement des couleurs vives','uniquement de la musique'],'Cela aide à capter l’attention.'],
  ['Doit-on obligatoirement vouloir exercer le métier qu’on présente ?','non, on peut le présenter par simple curiosité',['oui, c’est obligatoire','oui, sinon la présentation est interdite','oui, sous peine de sanction'],'Présenter un métier aide aussi à explorer.'],
  ['Pourquoi s’informer sur le salaire moyen d’un métier peut être utile ?','pour avoir une idée réaliste des conditions de vie liées à ce métier',['pour se vanter','ce n’est jamais utile','pour impressionner le jury uniquement'],'C’est un critère parmi d’autres.',2],
  ['Une présentation de métier doit comporter…','une introduction, des parties et une conclusion',['uniquement des images sans texte','uniquement une conclusion','aucune organisation particulière'],'Une structure claire aide l’auditoire à suivre.'],
  ['Témoigner d’un professionnel rencontré dans sa présentation est…','un bon moyen de rendre son exposé concret',['interdit','inutile','une perte de temps'],'Les exemples concrets enrichissent la présentation.'],
  ['Pour présenter un secteur d’activité plutôt qu’un seul métier, on peut citer…','plusieurs métiers représentatifs de ce secteur',['un seul métier sans aucun lien','aucun métier','uniquement des chiffres sans explication'],'Un secteur regroupe plusieurs métiers.'],
  ['Préparer une présentation à l’avance, plutôt que d’improviser, permet…','d’être plus clair et de ne pas oublier d’informations importantes',['de perdre du temps pour rien','de rendre la présentation moins intéressante','de décourager le public'],'La préparation améliore la qualité de l’exposé.']]),2])}
]);

MQ.add('orientation','4',[
{id:'orientation4a',name:'Faire le point sur ses compétences et motivations',icon:'📋',domain:'Connaissance de soi',
 refs:[AV,'Parcours Avenir — objectif « se connaître et développer ses compétences »'],
 tip:'Une motivation durable vient souvent de l’intérieur (« j’aime comprendre comment ça marche ») plus que de l’extérieur (« ça rapporte beaucoup d’argent »), même si les deux comptent.',
 c:C(`En 4e, le stage d’observation de 3e se prépare déjà : il est temps de faire un <b>bilan</b> plus précis de ses compétences, de ses motivations et de ce qui compte vraiment pour soi dans un futur métier.`,
  [T('Compétences et progrès',`<p>Un bilan de compétences, même simple, aide à voir ses progrès : qu’est-ce que je savais faire en 6e que je ne savais pas faire avant ? Qu’est-ce que j’aimerais encore développer ? On distingue les compétences <b>techniques</b> (savoir utiliser un logiciel, parler une langue) et les compétences <b>comportementales</b> (ponctualité, travail en équipe, autonomie).</p>`),
   T('Ce qui motive vraiment',`<p>Les <b>motivations</b> varient : le salaire, l’envie d’aider les autres, la passion pour un domaine, la recherche de stabilité, le goût du challenge, l’envie de créer. Aucune motivation n’est « meilleure » qu’une autre, mais les connaître aide à mieux choisir : un métier passionnant mais trop stressant pour soi ne conviendra peut-être pas.</p>`)],
  [{q:'Yanis veut devenir vétérinaire pour le salaire, mais il n’aime pas particulièrement les animaux. Que peut-on lui conseiller ?',s:['Réfléchir à ce qui motive réellement son choix.','Un métier choisi seulement pour le salaire risque de ne pas satisfaire sur la durée.','Explorer d’autres pistes qui combinent ses intérêts réels et une rémunération correcte.']}],
  ['Je fais le bilan de mes compétences techniques et comportementales.','Je repère mes progrès depuis la 6e.','J’identifie mes motivations profondes.','Je comprends qu’aucune motivation n’est meilleure qu’une autre, mais qu’il faut les connaître.'],
  ['Choisir un métier uniquement pour le salaire sans réfléchir à ses goûts.','Confondre compétence technique et compétence comportementale.','Croire que ses compétences sont figées depuis la 6e.'],
  ['Compétences techniques et comportementales.','Motivations variées : argent, passion, aide aux autres…','Bilan utile avant le stage de 3e.']),
 g:mix([sort({'Compétence technique':['savoir utiliser un tableur','parler une langue étrangère','savoir coder un petit programme'],'Compétence comportementale':['être ponctuel','savoir travailler en équipe','être autonome dans son travail']},{q:'« %s » est une compétence…'}),2],
  [bank([
   ['Une compétence technique est…','une capacité précise liée à un savoir-faire (logiciel, langue…)',['une qualité de comportement','un diplôme obligatoire','un salaire'],'Elle s’apprend souvent par la pratique.'],
   ['Une compétence comportementale est…','une qualité liée à la façon de travailler avec les autres (ponctualité, autonomie…)',['un logiciel','une langue étrangère','un diplôme'],'Elle compte beaucoup dans le monde professionnel.'],
   ['Choisir un métier uniquement pour le salaire, sans tenir compte de ses goûts, risque de…','ne pas satisfaire sur la durée',['garantir le bonheur à coup sûr','être la seule bonne méthode','n’avoir aucune conséquence'],'Les motivations profondes comptent aussi.'],
   {tf:'Les compétences évoluent au fil du collège.',v:true,e:'On progresse avec l’expérience et l’apprentissage.'},
   {tf:'Il existe une seule bonne motivation pour choisir un métier.',v:false,e:'Plusieurs motivations sont légitimes : argent, passion, aide aux autres…'},
   ['Pourquoi distinguer compétences techniques et comportementales ?','parce qu’un métier demande souvent les deux à la fois',['parce qu’une seule catégorie compte vraiment','ce n’est pas utile','parce que cela n’a aucun lien avec les métiers'],'Les deux types de compétences se complètent.'],
   ['Un bilan de compétences aide à…','voir ses progrès et ce qu’on aimerait encore développer',['oublier ses points faibles','choisir un métier au hasard','remplacer le bulletin scolaire'],'Il donne une vision plus claire de soi.'],
   ['La recherche de stabilité dans un métier est…','une motivation légitime parmi d’autres',['une mauvaise motivation','interdite','la seule motivation valable'],'Chaque motivation a sa valeur.']]),2])},

{id:'orientation4b',name:'Comparer métiers, conditions de travail et compétences',icon:'📊',domain:'Monde professionnel',
 refs:[AV,ONI,'Parcours Avenir — objectif « découvrir le monde économique et professionnel »'],
 tip:'Un même métier peut avoir des conditions de travail très différentes selon l’employeur : horaires, lieu, en équipe ou seul, à l’extérieur ou au bureau.',
 c:C(`Comparer plusieurs métiers permet de mieux comprendre ce qui compte pour soi : <b>horaires</b>, <b>lieu de travail</b>, <b>travail en équipe ou seul</b>, <b>niveau d’études</b>, <b>évolution possible</b>.`,
  [T('Des conditions de travail variées',`<p>Certains métiers s’exercent en <b>horaires décalés</b> (nuit, week-end : infirmier, boulanger), d’autres en horaires classiques (bureau). Certains s’exercent en <b>extérieur</b> (agriculteur, paysagiste), d’autres en <b>intérieur</b>. Certains demandent de <b>voyager</b>, d’autres non. Ces conditions influencent fortement la qualité de vie au travail.</p>`),
   T('Évolution et formation continue',`<p>Un métier peut évoluer avec l’expérience (devenir responsable, se spécialiser) grâce à la <b>formation continue</b>. Certains secteurs recrutent beaucoup (on parle de métiers « en tension »), d’autres moins. Comparer ces éléments aide à anticiper, sans qu’aucun critère ne doive dominer les autres.</p>`)],
  [{q:'Compare le métier de boulanger et celui de professeur selon les horaires.',s:['Le boulanger travaille souvent très tôt le matin, parfois le week-end.','Le professeur travaille en journée, avec des congés scolaires.','Ces horaires différents conviennent à des personnes différentes.']}],
  ['Je compare plusieurs métiers selon des critères objectifs.','Je repère les différences d’horaires et de lieu de travail.','Je comprends qu’un métier peut évoluer avec l’expérience.','Je sais qu’aucun critère ne doit dominer les autres seuls.'],
  ['Croire que tous les métiers ont les mêmes horaires.','Ignorer qu’un métier peut évoluer dans le temps.','Juger un métier uniquement sur un seul critère.'],
  ['Horaires, lieu, équipe ou solo.','Évolution possible, formation continue.','Comparer plusieurs critères.']),
 g:mix([bank([
  ['Quel métier s’exerce typiquement en horaires décalés (très tôt le matin) ?','boulanger ou boulangère',['professeur des écoles','employé de bureau administratif','bibliothécaire'],'La fabrication du pain commence très tôt.'],
  ['La formation continue permet…','de développer de nouvelles compétences tout au long de sa carrière',['de redoubler une classe','d’arrêter de travailler','de changer de nom'],'On peut apprendre après ses études initiales.'],
  ['Un métier « en tension » signifie…','que le secteur recrute beaucoup et manque de candidats',['que le métier est dangereux','que le salaire est très bas','que le métier n’existe plus'],'Exemples fréquents : certains métiers de la santé ou du bâtiment.',2],
  {tf:'Un métier peut évoluer (responsabilités, spécialisation) avec l’expérience.',v:true,e:'Grâce notamment à la formation continue.'},
  {tf:'Tous les métiers s’exercent dans les mêmes conditions de travail.',v:false,e:'Horaires, lieu et rythme varient beaucoup selon le métier.'},
  ['Quel métier s’exerce typiquement en extérieur ?','agriculteur ou agricultrice',['comptable','employé de banque','secrétaire médical'],'Beaucoup de métiers agricoles s’exercent en plein air.'],
  ['Travailler « seul » plutôt qu’« en équipe » dépend…','du métier et de l’organisation de l’entreprise',['toujours du salaire','toujours de l’âge','d’aucun facteur particulier'],'Certains métiers sont plus solitaires, d’autres plus collectifs.'],
  ['Comparer les conditions de travail de plusieurs métiers permet…','de mieux anticiper ce qui conviendra à soi-même',['de choisir au hasard','de ne rien apprendre','de perdre du temps'],'Chacun a des préférences différentes.'],
  ['Un métier qui demande de voyager régulièrement convient…','à ceux que cela attire, pas à tout le monde',['à absolument tout le monde','à personne jamais','uniquement aux adultes de plus de 40 ans'],'C’est un critère personnel parmi d’autres.'],
  ['Pourquoi aucun critère ne doit-il dominer tous les autres dans le choix d’un métier ?','parce que l’équilibre entre plusieurs critères compte (horaires, lieu, intérêt, salaire…)',['parce que le salaire est le seul critère valable','parce qu’aucun critère n’a d’importance','parce que c’est interdit par la loi'],'Un bon choix tient compte de plusieurs éléments à la fois.',2],
  ['Travailler en intérieur, dans un bureau, convient…','à certaines personnes, selon leurs préférences',['à tout le monde obligatoirement','à personne jamais','uniquement aux personnes malades'],'C’est une question de préférence personnelle.'],
  ['Un métier « en tension » offre souvent…','davantage de possibilités d’embauche',['moins de possibilités d’embauche','aucune possibilité d’embauche','uniquement des emplois à l’étranger'],'La demande de main-d’œuvre y est forte.']]),2])},

{id:'orientation4c',name:'Découvrir lycée général, technologique et professionnel',icon:'🏫',domain:'Parcours scolaire',
 refs:[AV,'Code de l’éducation — organisation des voies du lycée'],
 tip:'En voie générale, les spécialités se choisissent en 2de pour la 1re ; en voie technologique, la série est choisie dès l’entrée en 1re ; en voie professionnelle, la spécialité est choisie dès la 2de professionnelle.',
 c:C(`Avant de choisir une voie après la 3e, il est utile de bien comprendre leur <b>fonctionnement</b> : organisation des années, matières, spécialités.`,
  [T('La voie générale',`<p>En <b>2de générale et technologique</b>, un tronc commun avec quelques enseignements optionnels. En <b>1re</b>, l’élève choisit des <b>spécialités</b> (par exemple mathématiques, physique-chimie, histoire-géographie, langues, arts, SES…) qu’il garde en partie en <b>terminale</b>. Le <b>baccalauréat général</b> se prépare en 3 ans (2de, 1re, terminale).</p>`),
   T('La voie technologique et la voie professionnelle',`<p>La <b>voie technologique</b> propose des <b>séries</b> (STI2D, STMG, ST2S, STL…) choisies dès la 1re, combinant enseignement général et technologique. La <b>voie professionnelle</b> (en lycée professionnel) prépare, en 3 ans, à un <b>bac professionnel</b> dans un domaine précis (par exemple commerce, mécanique, esthétique), avec des <b>périodes de stage en entreprise</b> ; elle permet aussi de préparer un <b>CAP</b> en 2 ans.</p>`)],
  [{q:'Léa aime les sciences et veut garder des options variées avant de se spécialiser. Quelle voie lui convient le mieux au départ ?',s:['La voie générale, avec un tronc commun en 2de.','Elle choisira ses spécialités en fin de 2de, pour la 1re.','Elle garde ainsi plusieurs options ouvertes.']}],
  ['Je distingue 2de, 1re et terminale.','Je comprends le principe des spécialités en voie générale.','Je connais quelques séries technologiques.','Je comprends l’organisation du bac professionnel.'],
  ['Confondre spécialité (voie générale) et série (voie technologique).','Croire que le bac professionnel ne contient aucun stage.','Penser que le CAP dure 3 ans comme le bac.'],
  ['Générale : spécialités en 1re.','Technologique : séries dès la 1re.','Professionnelle : bac pro (3 ans) ou CAP (2 ans), stages.']),
 g:mix([pairs([['STI2D','série technologique sciences et technologies de l’industrie et du développement durable'],['STMG','série technologique sciences et technologies du management et de la gestion'],['ST2S','série technologique sciences et technologies de la santé et du social']],{q:'%s désigne la…',rq:'Quel sigle correspond à : %s ?'}),1],
  [bank([
   ['En voie générale, les spécialités se choisissent…','à la fin de la 2de, pour la 1re',['dès la 6e','à la fin de la 3e','en terminale seulement'],'Le tronc commun de 2de précède ce choix.'],
   ['Le bac professionnel se prépare en…','3 ans, avec des périodes de stage',['1 an','5 ans sans aucun stage','10 ans'],'Comme le bac général et le bac technologique.'],
   ['Le CAP se prépare en…','2 ans en général',['5 ans','1 mois','10 ans'],'C’est une formation courte et qualifiante.'],
   {tf:'En voie technologique, la série est choisie dès l’entrée en 1re.',v:true,e:'Contrairement aux spécialités de la voie générale, plus modulables.'},
   {tf:'Toutes les voies du lycée durent exactement le même nombre d’années sans aucune exception.',v:false,e:'Le CAP dure 2 ans, les baccalauréats 3 ans après la 3e (2de, 1re, terminale).'},
   ['La classe de 2de générale et technologique propose…','un tronc commun avec quelques enseignements optionnels',['uniquement des spécialités définitives','uniquement des matières professionnelles','aucune matière commune'],'Les spécialités viennent ensuite, en 1re.'],
   ['STMG est une série…','technologique, orientée gestion et management',['professionnelle uniquement','générale uniquement','réservée aux adultes'],'Sciences et technologies du management et de la gestion.',2],
   ['Un bac professionnel peut se préparer dans des domaines comme…','le commerce, la mécanique ou l’esthétique',['uniquement les mathématiques','uniquement les langues anciennes','aucun domaine précis'],'Il existe de nombreuses spécialités professionnelles.']]),2])},

{id:'orientation4d',name:'Préparer une rencontre, visite ou mini-stage',icon:'🗂️',domain:'Exploration',
 refs:[AV,'Parcours Avenir — objectif « découvrir le monde économique et professionnel »'],
 tip:'Un mini-stage ou une visite réussis se préparent à l’avance (tenue adaptée, horaires, questions) et se concluent par un petit bilan écrit.',
 c:C(`Visiter une entreprise, participer à un forum des métiers, échanger lors d’un « mini-stage » (demi-journée d’observation) : ces expériences, préparées en amont de la 3e, enrichissent le <b>parcours Avenir</b>.`,
  [T('Avant la visite',`<p>Se renseigner sur le lieu, le secteur, préparer une <b>tenue adaptée</b> si besoin, préparer des questions (voir le chapitre de 6e sur les questions ouvertes), connaître les <b>horaires</b> et le lieu exact du rendez-vous, prévenir en cas d’empêchement.</p>`),
   T('Pendant et après',`<p>Pendant : observer, écouter, noter, respecter les règles de sécurité et de politesse du lieu. Après : écrire un petit <b>bilan</b> (ce qui a été appris, aimé, moins aimé), remercier la personne qui a accueilli. Ce bilan complète le carnet de découvertes commencé en 6e.</p>`)],
  [{q:'Avant une visite d’usine, que préparer ?',s:['Se renseigner sur l’activité de l’usine.','Prévoir une tenue adaptée (chaussures fermées, pas de vêtements amples près des machines).','Préparer quelques questions à poser au responsable.']}],
  ['Je me renseigne avant la visite.','Je prépare une tenue adaptée si nécessaire.','Je prépare des questions.','J’écris un bilan après la visite et je remercie l’accueil.'],
  ['Arriver sans aucune préparation.','Oublier de prévenir en cas d’empêchement.','Ne pas respecter les règles de sécurité du lieu.'],
  ['Préparer : renseignements, tenue, questions, horaires.','Pendant : observer, noter, respecter les règles.','Après : bilan et remerciement.']),
 g:mix([bank([
  ['Avant une visite d’entreprise, il est utile de…','se renseigner sur son activité et préparer des questions',['ne rien préparer','venir en retard','ignorer les règles de sécurité'],'Cela permet d’en profiter pleinement.'],
  ['Pendant une visite dans un atelier, il faut souvent…','porter une tenue adaptée (chaussures fermées, pas de vêtements amples)',['porter des sandales ouvertes','porter une écharpe très longue près des machines','venir en tenue de sport mouillée'],'La sécurité prime.'],
  ['Après une visite, il est utile de…','écrire un bilan et remercier la personne qui a accueilli',['oublier immédiatement ce qui a été vu','ne jamais en reparler','critiquer publiquement l’accueil'],'Cela montre aussi de la politesse.'],
  {tf:'Il faut prévenir si on ne peut finalement pas se rendre à une visite programmée.',v:true,e:'C’est une question de politesse envers les organisateurs.'},
  {tf:'Les règles de sécurité d’un atelier ne s’appliquent pas aux visiteurs.',v:false,e:'Elles s’appliquent à tous, y compris aux visiteurs.'},
  ['Que faire si on ne peut finalement pas se rendre à une visite programmée ?','prévenir les organisateurs le plus tôt possible',['ne rien dire','venir quand même en retard sans prévenir','annuler sans explication au dernier moment'],'C’est une question de politesse et d’organisation.'],
  ['Un mini-stage d’observation dure généralement…','quelques heures à une demi-journée',['plusieurs mois','une seule minute','plusieurs années'],'C’est une courte immersion.',2],
  ['Observer en silence et prendre des notes pendant une visite permet…','de mieux se souvenir ensuite de ce qui a été vu',['de perdre son temps','de déranger les professionnels','de ne rien apprendre'],'Cela complète le carnet de découvertes.'],
  ['Connaître à l’avance les horaires et le lieu exact d’un rendez-vous professionnel permet…','d’éviter d’arriver en retard ou au mauvais endroit',['de perdre du temps','de ne rien apprendre','d’éviter toute préparation'],'C’est une organisation de base.'],
  ['Un forum des métiers organisé au collège permet…','de rencontrer plusieurs professionnels en une seule journée',['de signer un contrat de travail','de passer un examen officiel','de choisir définitivement son orientation'],'C’est une occasion d’explorer plusieurs pistes à la fois.'],
  ['Avant une visite, vérifier le moyen de transport et le temps de trajet permet…','d’arriver à l’heure sans stress',['de perdre du temps pour rien','de déranger les organisateurs','ce n’est jamais utile'],'Une bonne organisation évite les retards.'],
  ['Si une visite d’entreprise est annulée par l’organisme d’accueil, l’élève doit…','en être informé et chercher éventuellement une autre occasion',['continuer sans en être informé','considérer que le parcours Avenir est terminé','abandonner toute démarche de découverte'],'Ce type d’imprévu peut arriver et se gère normalement.']]),2])},

{id:'orientation4e',name:'Construire un projet provisoire et argumenté',icon:'🧱',domain:'Projet',
 refs:[AV,'Parcours Avenir — objectif « élaborer son projet d’orientation scolaire et professionnelle »'],
 tip:'Un projet « provisoire » n’est pas un échec si on en change : c’est un point de départ pour explorer, se renseigner et avancer.',
 c:C(`À la fin de la 4e, il est utile de formuler un <b>projet provisoire</b> : une ou plusieurs pistes de métier ou de voie de formation, avec des <b>arguments</b> qui expliquent ce choix. Ce projet n’est pas définitif : il pourra évoluer en 3e et au lycée.`,
  [T('Un projet, pas une décision figée',`<p>Un projet <b>provisoire</b> aide à se donner une direction sans être une décision irréversible. Il peut comporter plusieurs pistes (par exemple deux ou trois métiers qui intéressent). L’important est de pouvoir <b>expliquer pourquoi</b> : lien avec ses goûts, ses compétences, ses découvertes (visites, rencontres, carnet).</p>`),
   T('Argumenter son projet',`<p>Un bon argument relie un <b>fait</b> (une compétence, une expérience, une information sur le métier) à une <b>conclusion</b> (pourquoi cette piste m’intéresse). Exemple : « J’aime résoudre des problèmes techniques (fait) et le métier de technicien en informatique demande cette compétence (information) : c’est pourquoi cette piste m’intéresse (conclusion). »</p>`)],
  [{q:'Formule un projet provisoire argumenté pour un élève qui aime les sciences et le contact avec les gens.',s:['Piste envisagée : métier du soin (infirmier, kinésithérapeute).','Argument : goût pour les sciences du vivant et l’aide aux autres.','Ce projet pourra être affiné après le stage de 3e.']}],
  ['Je formule une ou plusieurs pistes.','J’appuie mon projet sur des arguments (goûts, compétences, découvertes).','Je garde en tête que ce projet est provisoire.','J’accepte qu’il puisse évoluer.'],
  ['Croire qu’un projet provisoire doit être définitif.','Choisir une piste sans aucun argument.','Avoir honte de changer d’avis plus tard.'],
  ['Projet provisoire : point de départ, pas décision figée.','Argument = fait + conclusion.','Évolution possible après la 3e.']),
 g:mix([bank([
  ['Un projet provisoire est…','une direction qui peut évoluer avec le temps',['une décision définitive et irréversible','interdit avant la 3e','obligatoire dès la 6e'],'Il laisse la place à l’exploration.'],
  ['Un bon argument pour un projet d’orientation relie…','un fait (compétence, expérience) à une conclusion (pourquoi cette piste intéresse)',['uniquement une opinion sans preuve','le hasard à une décision','rien à rien'],'Exemple : aimer les sciences → intérêt pour un métier scientifique.'],
  ['Changer de projet d’orientation entre la 4e et la 3e est…','normal et sans conséquence négative',['un échec','interdit','rare et grave'],'Le projet se construit progressivement.'],
  {tf:'Il est possible d’avoir plusieurs pistes de métiers en tête en même temps.',v:true,e:'Un projet provisoire peut comporter plusieurs pistes.'},
  {tf:'Un projet d’orientation doit être choisi sans aucun argument, au hasard.',v:false,e:'Il doit s’appuyer sur ses goûts, compétences et découvertes.'},
  ['Un projet provisoire peut-il comporter plusieurs métiers envisagés ?','oui, plusieurs pistes sont possibles',['non, un seul métier doit être choisi','non, c’est interdit','non, cela n’a pas de sens'],'On peut explorer plusieurs directions à la fois.'],
  ['À la fin de la 4e, le projet d’orientation sert surtout à…','se donner une direction à explorer, pas à décider définitivement',['obtenir une note','remplacer le brevet','signer un contrat de travail'],'Il évoluera encore en 3e et au lycée.'],
  ['Pour argumenter un projet, on peut s’appuyer sur…','ses expériences de visites, de rencontres ou de mini-stages',['uniquement son horoscope','uniquement l’avis d’un inconnu en ligne','rien de concret'],'Les expériences vécues nourrissent l’argumentation.'],
  ['Avoir deux pistes de métiers très différentes en 4e est-il gênant ?','non, cela permet d’explorer avant de préciser son choix',['oui, il faut n’en garder qu’une tout de suite','oui, c’est interdit','oui, cela retarde obligatoirement l’orientation'],'Le projet se précise progressivement.'],
  ['Un projet d’orientation en 4e doit-il déjà mentionner une voie précise (générale, professionnelle…) ?','pas obligatoirement, une piste de métier ou de domaine suffit souvent',['oui, absolument et définitivement','oui, sous peine de sanction','oui, sinon le projet est invalide'],'Le choix de voie se précisera notamment en 3e.'],
  ['Un projet d’orientation construit en 4e sera-t-il réexaminé en 3e ?','oui, notamment à l’occasion du stage et de la procédure d’orientation',['non, il est figé dès la 4e','non, personne n’y repense ensuite','non, cela n’a aucun lien avec la 3e'],'Le parcours Avenir se poursuit d’année en année.'],
  ['Pourquoi relier son projet à une expérience vécue (visite, rencontre) plutôt qu’à une simple impression ?','parce qu’un argument concret est plus solide qu’une impression vague',['parce que c’est plus rapide à écrire','parce que les impressions n’ont aucune valeur','parce que c’est obligatoire par la loi'],'Un fait vécu appuie mieux une conclusion.']]),2])}
]);

MQ.add('orientation','3',[
{id:'orientation3a',name:'Choisir son orientation après la 3e',icon:'🎯',domain:'Parcours scolaire',
 refs:[AV,PROC,'Code de l’éducation — procédure d’orientation en fin de troisième'],
 tip:'La décision finale d’orientation appartient à la famille, mais elle se construit en dialogue avec le conseil de classe, qui donne un avis.',
 c:C(`En fin de 3e, chaque élève et sa famille formulent des <b>vœux d’orientation</b> : voie générale et technologique, ou voie professionnelle. Cette décision suit une <b>procédure</b> précise, avec plusieurs étapes et des échanges avec l’équipe pédagogique.`,
  [T('Les étapes de la procédure',`<p>Au cours de l’année : <b>dialogue</b> avec les professeurs, le professeur principal, le psychologue de l’éducation nationale (<b>PsyEN</b>). Au <b>deuxième trimestre</b>, la famille formule des <b>vœux provisoires</b> ; le <b>conseil de classe</b> donne un avis. Au <b>troisième trimestre</b>, des <b>vœux définitifs</b> sont formulés ; le conseil de classe se prononce à nouveau, et la famille reçoit une <b>décision d’orientation</b>.</p>`),
   T('En cas de désaccord',`<p>Si la décision d’orientation ne correspond pas à la demande de la famille, un <b>dialogue</b> est possible avec le chef d’établissement ; une <b>commission d’appel</b> peut être saisie en dernier recours. La décision finale concernant le choix entre voie générale/technologique et voie professionnelle appartient en principe à la famille, après ce dialogue.</p>`)],
  [{q:'Au troisième trimestre, Camille et sa famille formulent un vœu pour la voie générale, mais le conseil de classe émet des réserves. Que se passe-t-il ?',s:['Un dialogue a lieu entre la famille et l’équipe pédagogique.','La famille peut maintenir son vœu après ce dialogue.','En cas de désaccord persistant, une commission d’appel peut être saisie.']}],
  ['Je connais les grandes étapes de la procédure d’orientation.','Je distingue vœux provisoires et vœux définitifs.','Je sais qui peut être consulté (professeurs, PsyEN).','Je comprends les recours possibles en cas de désaccord.'],
  ['Croire que l’orientation se décide en un seul jour.','Ignorer le rôle du conseil de classe.','Penser qu’aucun recours n’existe en cas de désaccord.'],
  ['Vœux provisoires (2e trimestre) puis définitifs (3e trimestre).','Conseil de classe : avis.','Dialogue, puis commission d’appel si besoin.']),
 g:mix([d=>order('Remets dans l’ordre les grandes étapes de la procédure d’orientation en 3e :',['Dialogue avec les professeurs et le PsyEN','Vœux provisoires de la famille','Avis du conseil de classe','Vœux définitifs de la famille','Décision d’orientation'],{expl:'Dialogue → vœux provisoires → avis → vœux définitifs → décision.'}),2],
  [bank([
   ['Que signifie PsyEN ?','psychologue de l’éducation nationale',['professeur spécialisé en nutrition','personnel de sécurité de l’établissement national','professionnel de l’énergie'],'Il peut aider à réfléchir à son orientation.'],
   ['Les vœux provisoires sont formulés…','au deuxième trimestre',['le premier jour de 3e','après le brevet','en 4e'],'Avant les vœux définitifs du troisième trimestre.'],
   ['Qui donne un avis sur les vœux d’orientation ?','le conseil de classe',['uniquement le ou la délégué(e) de classe','uniquement les parents','personne'],'Il se réunit après chaque série de vœux.'],
   ['En cas de désaccord persistant sur l’orientation, on peut saisir…','une commission d’appel',['la police','un tribunal civil','aucun recours n’existe'],'C’est le dernier recours prévu par la procédure.',2],
   {tf:'La famille formule des vœux d’orientation à deux moments de l’année de 3e.',v:true,e:'Vœux provisoires puis vœux définitifs.'},
   {tf:'Le conseil de classe décide seul, sans aucun dialogue avec la famille.',v:false,e:'Un dialogue est prévu en cas de désaccord.'},
   ['À qui appartient en principe la décision finale entre voie générale/technologique et voie professionnelle ?','à la famille, après dialogue avec l’équipe pédagogique',['uniquement au conseil de classe','uniquement au ou à la délégué(e) de classe','uniquement au ministère'],'La famille décide, en tenant compte des avis donnés.'],
   ['Un dialogue avec le chef d’établissement intervient…','en cas de désaccord entre la famille et le conseil de classe',['avant même la première réunion','jamais, ce n’est pas prévu','uniquement pour les meilleurs élèves'],'Il précède la commission d’appel si besoin.'],
   ['Les vœux définitifs sont formulés…','au troisième trimestre',['au premier trimestre','en 4e','après l’obtention du brevet'],'Après les vœux provisoires du deuxième trimestre.'],
   ['Le professeur principal joue, dans la procédure d’orientation, un rôle…','de dialogue et d’accompagnement de l’élève et de sa famille',['uniquement administratif, sans aucun dialogue','aucun rôle particulier','décisionnaire exclusif, sans recours possible'],'Il fait le lien entre l’équipe pédagogique et la famille.'],
   ['Une décision d’orientation est transmise à la famille…','après le conseil de classe du troisième trimestre',['avant même la rentrée en 3e','sans jamais de dialogue possible','uniquement par voie postale obligatoire'],'Elle suit les vœux définitifs et l’avis du conseil de classe.']]),2])},

{id:'orientation3b',name:'Comprendre les voies générale, technologique, professionnelle et apprentissage',icon:'🧭',domain:'Parcours scolaire',
 refs:[AV,'Code de l’éducation — voies de formation après la classe de troisième'],
 tip:'Toutes les voies peuvent mener à des études supérieures : la voie professionnelle aussi, via un BTS ou un BUT par exemple.',
 c:C(`Après la 3e, quatre grandes options existent : la voie <b>générale et technologique</b>, la voie <b>professionnelle</b> (lycée professionnel), l’<b>apprentissage</b> et, plus rarement à cet âge, d’autres parcours spécifiques. Les comprendre en détail aide à choisir.`,
  [T('Récapitulatif des voies',`<p><b>Voie générale et technologique</b> (lycée) : 2de, puis 1re et terminale avec spécialités ou série, bac en 3 ans, poursuite d’études fréquente. <b>Voie professionnelle</b> (lycée professionnel) : CAP (2 ans) ou bac professionnel (3 ans), avec <b>périodes de stage</b> obligatoires. <b>Apprentissage</b> : possible dès la voie professionnelle, formation en <b>CFA</b> (centre de formation d’apprentis) alternée avec le travail en entreprise, sous contrat.</p>`),
   T('Et après ?',`<p>Toutes les voies peuvent mener à une poursuite d’études : un bac professionnel peut être suivi d’un <b>BTS</b> ; un bac général ou technologique peut être suivi de l’<b>université</b>, d’un <b>BUT</b>, d’une <b>école</b>. Le choix dépend du projet de chacun, pas d’un classement entre les voies.</p>`)],
  [{q:'Un élève veut devenir mécanicien automobile tout en étant rémunéré pendant sa formation. Quelle voie choisir ?',s:['L’apprentissage, en lycée professionnel ou CFA.','Il alterne cours théoriques et travail en garage, sous contrat.','Il pourra ensuite, s’il le souhaite, poursuivre vers un BTS.']}],
  ['Je connais les quatre grandes options après la 3e.','Je comprends ce qu’est un CFA.','Je sais que toutes les voies peuvent mener à des études supérieures.','Je ne classe pas les voies entre elles.'],
  ['Croire que la voie professionnelle empêche de poursuivre des études.','Confondre lycée professionnel et CFA.','Penser qu’une seule voie « vaut mieux » que les autres.'],
  ['4 options : générale/technologique, professionnelle, apprentissage.','CFA : formation en alternance.','Toutes les voies peuvent mener à des études supérieures.']),
 g:mix([pairs([['CFA','centre de formation d’apprentis'],['BTS','brevet de technicien supérieur, après le bac, en 2 ans'],['BUT','bachelor universitaire de technologie, après le bac, en 3 ans']],{q:'%s désigne…',rq:'Quel sigle correspond à : %s ?'}),1],
  [bank([
   ['L’apprentissage se déroule…','en alternance entre un CFA et une entreprise, sous contrat',['uniquement en salle de classe','uniquement en entreprise sans aucun cours','sans aucun contrat'],'L’apprenti est rémunéré.'],
   ['Un bac professionnel peut-il être suivi d’études supérieures ?','oui, par exemple un BTS',['non, jamais','seulement à l’étranger','seulement après 10 ans'],'La voie professionnelle n’empêche pas la poursuite d’études.'],
   ['Un CFA est…','un centre de formation d’apprentis',['un diplôme','une matière scolaire','un concours'],'On y suit la partie théorique de l’apprentissage.',2],
   {tf:'Toutes les voies après la 3e peuvent mener, à terme, à des études supérieures.',v:true,e:'Même la voie professionnelle, via un BTS par exemple.'},
   {tf:'La voie professionnelle est automatiquement « moins bien » que la voie générale.',v:false,e:'Chaque voie correspond à un projet différent, sans hiérarchie.'},
   ['Le BUT se prépare…','à l’université, en 3 ans après le bac',['au collège','en CAP','avant le brevet'],'Bachelor universitaire de technologie.'],
   ['L’apprentissage est-il réservé à certains métiers seulement ?','non, il existe dans de très nombreux secteurs',['oui, uniquement dans l’agriculture','oui, uniquement dans l’informatique','oui, uniquement dans la restauration'],'On le trouve dans de nombreux domaines.',2],
   ['Après un bac général, une poursuite d’études fréquente est…','l’université',['obligatoirement un CFA','obligatoirement l’arrêt des études','obligatoirement un CAP'],'D’autres voies existent aussi (écoles, prépas…).']]),2])},

{id:'orientation3c',name:'Préparer stage, CV, présentation et entretien',icon:'💼',domain:'Insertion',
 refs:[OBS,AV,'Parcours Avenir — objectif « élaborer son projet d’orientation scolaire et professionnelle »'],
 tip:'Un CV de collégien n’a pas besoin d’expérience professionnelle : il peut présenter ses centres d’intérêt, ses compétences et ses engagements (club, association).',
 c:C(`La <b>séquence d’observation en milieu professionnel</b> (le « stage de 3e ») demande une préparation : trouver un lieu d’accueil, rédiger un <b>CV</b> simple, se présenter, parfois passer un petit <b>entretien</b>.`,
  [T('Trouver un lieu de stage',`<p>On cherche un lieu en lien avec un centre d’intérêt (ou pour découvrir un domaine inconnu), on contacte l’entreprise ou l’organisme (par téléphone, courriel ou en personne), avec <b>politesse</b> et en expliquant sa demande clairement. Une <b>convention de stage</b>, signée par le collège, l’élève (ou sa famille) et l’organisme d’accueil, encadre légalement cette période.</p>`),
   T('CV et entretien',`<p>Un <b>CV</b> de collégien présente : identité, classe, centres d’intérêt, compétences, engagements (club, association, responsabilités). Lors d’un entretien ou d’un appel : se présenter clairement, expliquer pourquoi ce lieu intéresse, poser des questions sur le déroulement du stage, remercier à la fin de l’échange.</p>`)],
  [{q:'Un élève souhaite faire son stage dans une bibliothèque. Prépare sa démarche.',s:['Rechercher les coordonnées de la bibliothèque municipale.','Rédiger un courriel poli expliquant sa demande de stage et ses motivations.','Préparer quelques phrases pour se présenter si un entretien téléphonique est proposé.']}],
  ['Je cherche un lieu de stage en lien avec mes centres d’intérêt.','Je rédige un CV simple et clair.','Je prépare ma présentation pour un entretien.','Je sais qu’une convention de stage encadre légalement la période.'],
  ['Contacter une entreprise sans aucune politesse.','Oublier de préparer ce qu’on va dire lors d’un entretien.','Ignorer qu’une convention de stage est nécessaire.'],
  ['Recherche de lieu, convention de stage.','CV simple : identité, centres d’intérêt, compétences, engagements.','Entretien : se présenter, poser des questions, remercier.']),
 g:mix([sort({'À mettre dans un CV de collégien':['ses centres d’intérêt','ses compétences (langues, informatique…)','ses engagements associatifs ou dans un club'],'À ne pas mettre dans un CV de collégien':['son numéro de sécurité sociale','des informations médicales confidentielles','des informations inventées']},{q:'« %s » : dans un CV de collégien ?'}),1],
  [bank([
   ['Que signifie « convention de stage » ?','un document qui encadre légalement la période de stage',['un diplôme obtenu après le stage','un contrat de travail rémunéré','une note scolaire'],'Elle est signée par le collège, l’élève et l’organisme d’accueil.'],
   ['Dans un CV de collégien, on peut présenter…','ses centres d’intérêt et ses engagements (club, association)',['uniquement une longue expérience professionnelle','rien du tout','uniquement ses bulletins scolaires'],'L’absence d’expérience professionnelle n’empêche pas de se présenter.'],
   ['Lors d’un entretien téléphonique pour un stage, il est utile de…','se présenter clairement et expliquer sa motivation',['parler le plus vite possible','raccrocher sans se présenter','ne poser aucune question'],'Une présentation claire fait bonne impression.'],
   {tf:'Il faut remercier la personne à la fin d’un entretien, même téléphonique.',v:true,e:'C’est une marque de politesse qui compte.'},
   {tf:'Un stage de 3e peut se faire sans aucune convention signée.',v:false,e:'La convention encadre légalement la période d’observation.'},
   ['Qui signe la convention de stage de 3e ?','le collège, l’élève (ou sa famille) et l’organisme d’accueil',['uniquement l’élève','uniquement l’organisme d’accueil','personne, ce n’est pas nécessaire'],'Trois parties sont engagées.'],
   ['Pour chercher un lieu de stage, on peut d’abord contacter…','une entreprise ou un organisme en lien avec un centre d’intérêt',['n’importe qui au hasard sans aucun lien avec ses envies','uniquement une grande entreprise internationale','uniquement un inconnu en ligne'],'Un lien avec ses centres d’intérêt facilite la recherche.'],
   ['Lors d’un entretien pour un stage, poser des questions sur le déroulement du stage montre…','de l’intérêt et de la préparation',['du désintérêt','de l’impolitesse','de la timidité excessive'],'Cela donne une bonne impression.']]),2])},

{id:'orientation3d',name:'Relier compétences, métiers et formations',icon:'🔗',domain:'Projet',
 refs:[AV,ONI,'Parcours Avenir — objectif « élaborer son projet d’orientation scolaire et professionnelle »'],
 tip:'Pour relier une compétence à un métier, demande-toi : « Qu’est-ce que je sais déjà faire qui pourrait être utile dans ce métier ? »',
 c:C(`Après avoir identifié ses compétences (4e) et exploré des métiers (6e, 5e), en 3e on apprend à <b>relier</b> ces éléments : quelles compétences sont utiles pour quel métier, quelle <b>formation</b> y mène ?`,
  [T('De la compétence au métier',`<p>Une compétence (par exemple « être minutieux ») est utile dans certains métiers (horloger, chirurgien, bijoutier) et moins dans d’autres. Un métier demande souvent plusieurs compétences à la fois : techniques, mais aussi comportementales (rigueur, créativité, sens du contact).</p>`),
   T('Du métier à la formation',`<p>Chaque métier est accessible par une ou plusieurs <b>formations</b> possibles (parfois plusieurs chemins mènent au même métier). On vérifie les <b>diplômes requis</b> en consultant l’Onisep ou des sites spécialisés, car les voies d’accès évoluent avec le temps.</p>`)],
  [{q:'Relie la compétence « être à l’aise avec les chiffres » à un métier et une formation possible.',s:['Métier possible : comptable.','Compétences utiles : rigueur, sens des chiffres, organisation.','Formation possible : BTS comptabilité et gestion, après le bac.']}],
  ['Je relie une compétence à un ou plusieurs métiers possibles.','Je comprends qu’un métier demande souvent plusieurs compétences.','Je recherche les formations qui mènent à un métier.','Je vérifie mes informations auprès de sources fiables.'],
  ['Croire qu’une seule compétence suffit pour un métier.','Penser qu’un seul chemin de formation existe toujours.','Se fier à des informations non vérifiées sur les diplômes requis.'],
  ['Compétence → métiers possibles.','Métier → formation(s) possible(s).','Vérifier auprès de sources fiables (Onisep).']),
 g:mix([pairs([['être minutieux et précis','horloger, chirurgien ou bijoutier'],['aimer convaincre et communiquer','commercial, avocat ou journaliste'],['être à l’aise avec les chiffres','comptable, actuaire ou statisticien'],['aimer créer et dessiner','designer, architecte ou illustrateur']],{q:'La compétence « %s » peut être utile pour devenir…',rq:'Quelle compétence est utile pour devenir : %s ?'}),2],
  [bank([
   ['Un métier demande en général…','plusieurs compétences à la fois, techniques et comportementales',['une seule compétence isolée','aucune compétence particulière','uniquement un diplôme sans compétence'],'Les compétences se combinent.'],
   ['Pour connaître les formations qui mènent à un métier précis, on consulte…','l’Onisep ou des sites spécialisés et fiables',['uniquement des rumeurs','uniquement les réseaux sociaux','rien, on devine'],'Les voies d’accès évoluent, il faut vérifier.'],
   ['Peut-il exister plusieurs chemins de formation pour un même métier ?','oui',['non, il n’y en a toujours qu’un seul','non, c’est interdit','non, c’est impossible'],'Par exemple, plusieurs diplômes peuvent mener au même métier.'],
   {tf:'La rigueur peut être une compétence utile dans de nombreux métiers différents.',v:true,e:'C’est une compétence comportementale transférable.'},
   {tf:'Il est inutile de vérifier les diplômes requis pour un métier, car ils ne changent jamais.',v:false,e:'Les voies d’accès peuvent évoluer avec le temps.'}]),2])},

{id:'orientation3e',name:'Construire et présenter son projet d’orientation',icon:'🎓',domain:'Projet',
 refs:[AV,PROC,'Parcours Avenir — objectif « élaborer son projet d’orientation scolaire et professionnelle »'],
 tip:'Un bon dossier d’orientation explique le « pourquoi » du choix (goûts, compétences, découvertes) et pas seulement le « quoi » (le nom de la voie choisie).',
 c:C(`En fin de 3e, il s’agit de rassembler tout le travail mené depuis la 6e (carnet de découvertes, bilans, rencontres, stage) pour construire et <b>présenter</b> un projet d’orientation argumenté.`,
  [T('Rassembler son parcours',`<p>Relire son <b>carnet de découvertes</b> (6e), ses bilans de compétences (4e), les notes prises lors de visites et du stage de 3e. Identifier ce qui a le plus marqué, ce qui a confirmé ou changé des idées de départ.</p>`),
   T('Présenter un projet argumenté',`<p>Un projet argumenté relie <b>goûts</b>, <b>compétences</b> et <b>découvertes</b> à une ou plusieurs <b>pistes de voie</b> (générale, technologique, professionnelle, apprentissage) et, éventuellement, de métier. Il reste <b>provisoire</b> : il pourra encore évoluer au lycée. Le présenter (à l’oral, par écrit) permet de recueillir des avis utiles (professeurs, PsyEN, famille) avant la décision finale.</p>`)],
  [{q:'Construis un projet d’orientation argumenté pour une élève passionnée de sciences qui a fait son stage dans un laboratoire.',s:['Elle a confirmé son goût pour les sciences pendant le stage.','Elle choisit la voie générale avec des spécialités scientifiques.','Elle garde en tête que ce choix pourra encore évoluer au lycée.']}],
  ['Je rassemble les traces de mon parcours depuis la 6e.','Je relie goûts, compétences et découvertes à une piste de voie.','Je présente mon projet de façon argumentée.','Je garde en tête que ce projet reste provisoire.'],
  ['Ignorer tout le travail fait depuis la 6e.','Choisir une voie sans lien avec ses découvertes.','Croire que ce choix est totalement définitif.'],
  ['Rassembler : carnet, bilans, stage.','Projet argumenté : goûts + compétences + découvertes.','Projet provisoire, encore évolutif au lycée.']),
 g:mix([bank([
  ['Pourquoi relire son carnet de découvertes en fin de 3e ?','pour voir l’évolution de ses idées depuis la 6e',['ce n’est jamais utile','pour le jeter','pour le recopier sans le lire'],'Il aide à construire un projet cohérent.'],
  ['Un projet d’orientation argumenté s’appuie sur…','les goûts, les compétences et les découvertes de l’élève',['uniquement le hasard','uniquement l’avis d’un camarade','uniquement une pièce de monnaie lancée'],'Plusieurs éléments se combinent.'],
  ['Présenter son projet à des adultes (professeurs, PsyEN, famille) permet…','de recueillir des avis utiles avant la décision finale',['de perdre du temps','d’être jugé négativement à coup sûr','de rendre le choix impossible'],'Le dialogue aide à affiner le projet.'],
  {tf:'Un projet d’orientation en fin de 3e peut encore évoluer au lycée.',v:true,e:'Rien n’est figé définitivement.'},
  {tf:'Le stage de 3e n’a aucun lien avec la construction du projet d’orientation.',v:false,e:'Il peut confirmer ou faire évoluer un projet.'},
  ['Un projet d’orientation peut s’appuyer sur une piste de voie…','générale, technologique, professionnelle ou en apprentissage',['uniquement générale','uniquement professionnelle','aucune voie en particulier'],'Toutes les voies sont des pistes possibles.'],
  ['Présenter son projet à l’oral permet notamment de…','s’entraîner à argumenter ses choix devant d’autres personnes',['d’éviter d’y réfléchir vraiment','de ne rien apprendre','de remplacer le conseil de classe'],'C’est un exercice utile pour la suite.'],
  ['Un projet resté « provisoire » en fin de 3e est-il un problème ?','non, il peut encore évoluer au lycée',['oui, c’est un échec','oui, il faut absolument tout savoir dès la 3e','oui, c’est interdit'],'L’orientation continue de se construire après la 3e.'],
  ['Quels éléments du parcours Avenir peuvent nourrir un bilan de fin de 3e ?','le carnet de découvertes, les bilans de compétences et le stage',['uniquement les notes de contrôle','uniquement l’avis d’un camarade','aucun élément particulier'],'Toutes les expériences accumulées depuis la 6e comptent.'],
  ['Demander l’avis de plusieurs adultes (professeurs, PsyEN, famille) avant de finaliser son projet est…','une bonne pratique qui aide à mieux décider',['une perte de temps','interdit','inutile puisque le choix est déjà fait'],'Plusieurs regards peuvent éclairer la décision.'],
  ['Un projet d’orientation en fin de 3e doit-il convaincre uniquement l’élève lui-même ?','non, il doit aussi pouvoir être expliqué et compris par les adultes qui accompagnent le choix',['oui, l’avis des adultes n’a aucune importance','oui, il doit rester totalement secret','oui, personne d’autre ne doit le connaître'],'Le dialogue avec les adultes fait partie de la procédure.'],
  ['Changer d’avis après avoir présenté un premier projet en 3e est…','possible, le projet peut encore être affiné jusqu’aux vœux définitifs',['interdit une fois le projet présenté','un échec grave','sans aucune conséquence sur la suite des étapes'],'La procédure prévoit plusieurs étapes successives.']]),2])}
]);

})();
